        ["MOD_DESC_101002"] = {
            ["ContentES"] = "Mejora el Ataque Cargado de Espada para infligir el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_101002",
            },
        ["MOD_DESC_101003"] = {
            ["ContentES"] = "Mejora el Ataque Cargado de Espada para invocar Sombras de espada que explotan al impactar o al desaparecer, infligiendo daño en un amplio área. Inflige el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_101003",
            },
        ["MOD_DESC_102001"] = {
            ["ContentES"] = "Mejora el Ataque Cargado de Arma de Asta para lanzar 5 lanzas hacia adelante, golpeando a todos los enemigos en tu trayectoria e infligiendo el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_102001",
            },
        ["MOD_DESC_102002"] = {
            ["ContentES"] = "Mejora el Ataque Descendente de Arma de Asta para generar una onda de choque más grande al impactar, infligiendo el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_102002",
            },
        ["MOD_DESC_102003"] = {
            ["ContentES"] = "Mejora el Ataque Normal de Arma de Asta para invocar lanzas espectrales que golpean al objetivo. Inflige el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_102003",
            },
        ["MOD_DESC_102004"] = {
            ["ContentES"] = "Mejora el Ataque Cargado de Arma de Asta para realizar un impulso hacia adelante, dañando a los enemigos en trayectoria e infligiendo el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_102004",
            },
        ["MOD_DESC_103001"] = {
            ["ContentES"] = "Mejora el Ataque Normal de Espadón para liberar tres Ondas de Espada en el golpe final, atravesando a los enemigos en tu trayectoria e infligiendo el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_103001",
            },
        ["MOD_DESC_103002"] = {
            ["ContentES"] = "Mejora el Ataque Cargado de Espadón para permitir moverse mientras se carga, capturando monstruos controlables a lo largo de tu trayectoria (hasta 4). Gastar puntos de Combo prolonga la duración de la carga. Al finalizar la carga o al liberar, desencadena un ataque de área amplio, que inflige el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_103002",
            },
        ["MOD_DESC_103003"] = {
            ["ContentES"] = "Mejora el Ataque Normal de Espadón para invocar engranajes giratorios que lanzan una ráfaga de golpes. Inflige el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_103003",
            },
        ["MOD_DESC_104001"] = {
            ["ContentES"] = "Mejora el Ataque Deslizante de Hojas Dobles convirtiéndolo en un impulso letal, cortando a todos los enemigos en tu trayectoria e infligiendo el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_104001",
            },
        ["MOD_DESC_104002"] = {
            ["ContentES"] = "Mejora el Ataque Normal de Hojas Dobles para combinar las dos espadas y realizar un ataque giratorio. Inflige el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_104002",
            },
        ["MOD_DESC_104003"] = {
            ["ContentES"] = "Mejora el Ataque Cargado de Hojas Dobles para combinar las espadas y lanzarlas hacia adelante, dañando a los enemigos en su trayectoria. Inflige el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_104003",
            },
        ["MOD_DESC_106001"] = {
            ["ContentES"] = "Mejora el Ataque Cargado de Katana. Al golpear a un enemigo, saltas y realizas un ataque descendente que inflige múltiples impactos a los enemigos cercanos e infligiendo el doble de daño que el ataque estándar.",
            ["TextMapId"] = "MOD_DESC_106001",
            },
        ["MOD_DESC_1311"] = {
            ["ContentES"] = "Disminuye el Daño Recibido en #1. Derrotar a un enemigo otorga 1 acumulación que aumenta el ATQ en #2 durante #3 s, hasta un máximo de #4 acumulaciones. La duración de este efecto se reinicia con cada nueva acumulación obtenida.",
            ["TextMapId"] = "MOD_DESC_1311",
