            },
        ["Message_Guide_Rouge3choose1_5"] = {
            ["ContentES"] = "Reúne suficientes mechas <H>del mismo tipo</> para desbloquear <H>Efectos Adicionales</> en el Laberinto místico.",
            ["TextMapId"] = "Message_Guide_Rouge3choose1_5",
            },
        ["Message_Guide_Rouge3choose1_6"] = {
            ["ContentES"] = "Selecciona aquí para <H>descartar la recompensa de mecha</> y obtener una pequeña cantidad de <H>Brasas</> en su lugar.",
            ["TextMapId"] = "Message_Guide_Rouge3choose1_6",
            },
        ["Message_Guide_Rouge3choose1_7"] = {
            ["ContentES"] = "Selecciona aquí para alternar la información de <H>Mecha</> entre vistas compactas y completas.",
            ["TextMapId"] = "Message_Guide_Rouge3choose1_7",
            },
        ["Message_Guide_Rouge3choose1_8"] = {
            ["ContentES"] = "Abre la página de <H>Cartera de exploración</> para comprobar tus mechas actuales.",
            ["TextMapId"] = "Message_Guide_Rouge3choose1_8",
            },
        ["Message_Guide_Rouge3choose1_8_Pad"] = {
            ["ContentES"] = "Presiona para abrir la página de <H>Cartera de exploración</> para comprobar tus mechas actuales.",
