            },
        ["Message_Guide_Rouge3choose1_9"] = {
            ["ContentES"] = "Revisa tus <H>Artefactos</> aquí. En comparación con las mechas, los artefactos proporcionan efectos más independientes y, a menudo, más poderosos.",
            ["TextMapId"] = "Message_Guide_Rouge3choose1_9",
            },
        ["Message_Guide_RougeContract_1"] = {
