        ["PartyReward_Description_110101"] = {
            ["ContentES"] = "Debajo de su cáscara amarga e incomestible se encuentran los granos dulces y ácidos del recuerdo.",
            ["TextMapId"] = "PartyReward_Description_110101",
            },
        ["PartyReward_Description_110102"] = {
            ["ContentES"] = "Una pluma rota, teñida con el sabor salado del mar y un leve rastro de sangre: evidencia de la ingenuidad y el coraje de una joven.",
            ["TextMapId"] = "PartyReward_Description_110102",
            },
        ["PartyReward_Description_110103"] = {
            ["ContentES"] = "Incluso desde dentro de una jaula, todavía hay quienes miran el horizonte.",
            ["TextMapId"] = "PartyReward_Description_110103",
            },
        ["PartyReward_Description_110104"] = {
            ["ContentES"] = "Los fugaces momentos de felicidad se han ido para siempre. Pero afortunadamente siempre hay un mañana.",
            ["TextMapId"] = "PartyReward_Description_110104",
            },
        ["PartyReward_Description_110301"] = {
            ["ContentES"] = "Diseñado meticulosamente en tamaño y forma, cubre a la perfección los cuernos cortados, permitiendo que cualquier joven parezca una persona ordinaria.",
            ["TextMapId"] = "PartyReward_Description_110301",
            },
        ["PartyReward_Description_110302"] = {
            ["ContentES"] = "Un periodista con grandilocuencia narra la vida legendaria de un rico comerciante, ensalzando su sabiduría, elegancia y generosidad… como si agitara de forma tentadora una pajita dorada ante el mundo.",
            ["TextMapId"] = "PartyReward_Description_110302",
            },
        ["PartyReward_Description_110303"] = {
            ["ContentES"] = "El número “47” grabado en el frío metal se ha desgastado hasta volverse casi ilegible, y desde entonces, el verdadero nombre de esta alma permanecerá desconocido para todos.",
            ["TextMapId"] = "PartyReward_Description_110303",
            },
        ["PartyReward_Description_110304"] = {
            ["ContentES"] = "Una luz brillante, cálida y a la vez suave llama a los niños para que regresen a casa. Sin embargo, para una bestia perdida en las sombras, esa luz siempre estará fuera de su alcance.",
            ["TextMapId"] = "PartyReward_Description_110304",
            },
        ["PartyReward_Description_150201"] = {
            ["ContentES"] = "El líquido carmesí oscuro sobre los fragmentos transparentes se solidificó desde hace mucho tiempo. Alguna vez, fue un milagro que una joven buscó desesperadamente.",
            ["TextMapId"] = "PartyReward_Description_150201",
            },
        ["PartyReward_Description_150202"] = {
            ["ContentES"] = "Un pergamino que guarda los sueños inconclusos de un joven y una muchacha. Es un legado, atemporal y puro, que fue confiado a las generaciones futuras.",
            ["TextMapId"] = "PartyReward_Description_150202",
            },
        ["PartyReward_Description_150203"] = {
            ["ContentES"] = "Hecha con carne fresca y verduras, esta sopa calentó una vez a un corazón, que había dejado de latir por un momento, en una noche gélida de invierno.",
            ["TextMapId"] = "PartyReward_Description_150203",
            },
        ["PartyReward_Description_150204"] = {
            ["ContentES"] = "En este sueño, no hay sufrimiento ni muerte, no hay arrepentimientos ni errores. Solo el sol y el arroyo, a su lado.",
            ["TextMapId"] = "PartyReward_Description_150204",
            },
        ["PartyReward_Description_150301"] = {
            ["ContentES"] = "Una espada puede matar — pero también puede cumplir otro propósito.",
            ["TextMapId"] = "PartyReward_Description_150301",
            },
        ["PartyReward_Description_150302"] = {
            ["ContentES"] = "Entre sueño y memoria, la errancia permanece libre; entre alegría y tristeza, una sonrisa melancólica ante el mundo.",
            ["TextMapId"] = "PartyReward_Description_150302",
            },
        ["PartyReward_Description_150303"] = {
            ["ContentES"] = "El menú amarillento de este puesto está lleno de platos de rara maestría, difíciles de encontrar en otro lugar.",
            ["TextMapId"] = "PartyReward_Description_150303",
            },
        }
  end },
  { MinKey = "PartyReward_Description_150304", MaxKey = "PartyTopic_Description_510104", Loader = function()
      return {
        ["PartyReward_Description_150304"] = {
            ["ContentES"] = "Una recopilación de relatos a medio camino entre la verdad y la ficción, antaño muy popular. Cuántos pasados atormentados y cuántas hojas cruzadas yacen en sus páginas, nadie podría decirlo.",
            ["TextMapId"] = "PartyReward_Description_150304",
            },
        ["PartyReward_Description_180101"] = {
            ["ContentES"] = "Un montón de casquillos usados ​​que, con un toque de imaginación, se transforman en pistolas, cañones, dirigibles y poderosos robots: claves para abrir un mundo de sueños.",
            ["TextMapId"] = "PartyReward_Description_180101",
            },
        ["PartyReward_Description_180102"] = {
            ["ContentES"] = "Los cuentos de hadas no siempre terminan en felicidad. Después de que el pájaro se convirtió en una estrella ardiente, ¿todavía llora en el cielo nocturno?",
            ["TextMapId"] = "PartyReward_Description_180102",
            },
        ["PartyReward_Description_180103"] = {
            ["ContentES"] = "Aunque las frías lluvias del pasado aún no han cesado, ella todavía siente el calor de la palma de otra persona.",
            ["TextMapId"] = "PartyReward_Description_180103",
            },
        ["PartyReward_Description_180104"] = {
            ["ContentES"] = "¿Hasta dónde deberá viajar antes de poder escribir un bello final para este cuento?",
            ["TextMapId"] = "PartyReward_Description_180104",
            },
        ["PartyReward_Description_210101"] = {
            ["ContentES"] = "Bébela. Traga la amargura del vaso y abraza la dulzura del amor.",
            ["TextMapId"] = "PartyReward_Description_210101",
            },
        ["PartyReward_Description_210102"] = {
            ["ContentES"] = "La medusa gira en el cristal bajo la luz, hundiéndose silenciosamente en las profundidades, sin encontrar compañía antes de disiparse al llegar al fondo del mar.",
            ["TextMapId"] = "PartyReward_Description_210102",
            },
        ["PartyReward_Description_210103"] = {
            ["ContentES"] = "Las relaciones a menudo reflejan esta bebida: comienzan con calidez, siguen con amargura y terminan con escalofríos. Al igual que el agua y el fuego, algunas cosas nunca estuvieron destinadas a mezclarse.",
            ["TextMapId"] = "PartyReward_Description_210103",
            },
        ["PartyReward_Description_210104"] = {
            ["ContentES"] = "Esta bebida es sencilla en apariencia y directa en sabor, porque el amor verdadero no necesita adornos: existe en la mirada de la persona amada.",
            ["TextMapId"] = "PartyReward_Description_210104",
            },
        ["PartyReward_Description_230101"] = {
            ["ContentES"] = "¡De un trago! La dulzura ácida irrumpe en tu lengua como la risa de un niño, crepitando y estallando en el porche.",
            ["TextMapId"] = "PartyReward_Description_230101",
            },
        ["PartyReward_Description_230102"] = {
            ["ContentES"] = "Lo dulce y lo salado no son opuestos, así como la inocencia y la travesura pueden coexistir.",
            ["TextMapId"] = "PartyReward_Description_230102",
            },
        ["PartyReward_Description_230103"] = {
            ["ContentES"] = "La acidez inicial te frunce el ceño, pero a medida que tus papilas gustativas se adaptan, florece una dulzura suave, muy parecido a entender el mundo: la esperanza siempre sigue a la tormenta.",
            ["TextMapId"] = "PartyReward_Description_230103",
            },
        ["PartyReward_Description_230104"] = {
            ["ContentES"] = "%*$^&!@#%*^^Y&!#(%^%???!!",
            ["TextMapId"] = "PartyReward_Description_230104",
            },
        ["PartyReward_Description_240101"] = {
            ["ContentES"] = "Un compendio que cataloga 1.890 sustancias medicinales, casi la mitad de ellas hierbas. El nombre del autor se lee: Fufeng.",
            ["TextMapId"] = "PartyReward_Description_240101",
            },
        ["PartyReward_Description_240102"] = {
            ["ContentES"] = "Casi idéntico en apariencia a Onírihierba, pero se sabe que induce alucinaciones. Si las alucinaciones son sueños despiertos, entonces su semejanza empieza a tener sentido.",
            ["TextMapId"] = "PartyReward_Description_240102",
            },
        ["PartyReward_Description_240103"] = {
            ["ContentES"] = "De apariencia extraña, en Huaxu es un preciado símbolo de longevidad.",
            ["TextMapId"] = "PartyReward_Description_240103",
            },
        ["PartyReward_Description_240104"] = {
            ["ContentES"] = "Aunque la lámpara de plata aún arde, temo que nuestro reencuentro no fue más que un sueño fugaz.",
            ["TextMapId"] = "PartyReward_Description_240104",
            },
        ["PartyReward_Description_310101"] = {
            ["ContentES"] = "Una bebida atrevida y picante para quienes buscan un impulso más fuerte. El primer sorbo abre el apetito y el segundo enciende el ánimo: una bebida perfecta para romper el hielo.",
            ["TextMapId"] = "PartyReward_Description_310101",
            },
        ["PartyReward_Description_310102"] = {
            ["ContentES"] = "Lo que pasa en el bar se queda en el bar: una regla tácita de cualquier buena sesión de bebidas.",
            ["TextMapId"] = "PartyReward_Description_310102",
            },
        ["PartyReward_Description_310103"] = {
            ["ContentES"] = "Puede que Lago Helado sea pequeño (un punto diminuto en el mapa del Imperio); sin embargo, Lago Helado es enorme: los recuerdos de él perduran sin importar lo lejos que uno viaje.",
            ["TextMapId"] = "PartyReward_Description_310103",
            },
        ["PartyReward_Description_310201"] = {
            ["ContentES"] = "Debajo de los pétalos hay espinas, ¿y debajo del dobladillo del vestido de una criada? Balas.",
            ["TextMapId"] = "PartyReward_Description_310201",
            },
        ["PartyReward_Description_310202"] = {
            ["ContentES"] = "Los disfraces no son magia sino una forma de arte, capaz de transformar no solo tu apariencia, sino también tu estado de ánimo.",
            ["TextMapId"] = "PartyReward_Description_310202",
            },
        ["PartyReward_Description_310203"] = {
            ["ContentES"] = "Menos mal que las tijeras en la mano de la criada sólo apunten a flores marchitas.",
            ["TextMapId"] = "PartyReward_Description_310203",
            },
        ["PartyReward_Description_310204"] = {
            ["ContentES"] = "Una taza de té de flores, el voto solemne de una criada.",
            ["TextMapId"] = "PartyReward_Description_310204",
            },
        ["PartyReward_Description_310301"] = {
            ["ContentES"] = "Aunque los nombres de los juguetes pueden variar, cada uno de ellos puede estallar en un hermoso espectáculo de fuegos artificiales.",
            ["TextMapId"] = "PartyReward_Description_310301",
            },
        ["PartyReward_Description_310302"] = {
            ["ContentES"] = "Una bebida energética poderosa, capaz de borrar la fatiga de los viajeros. Con la mente finalmente clara, el corazón puede entonces ver lo que realmente desea.",
            ["TextMapId"] = "PartyReward_Description_310302",
            },
        ["PartyReward_Description_310303"] = {
            ["ContentES"] = "Una bebida de potente efecto calmante, ideal para aliviar los nervios de quienes esperan con ansiedad. Solo mediante la paciencia, el corazón descubre lo que realmente anhela.",
            ["TextMapId"] = "PartyReward_Description_310303",
            },
        ["PartyReward_Description_310304"] = {
            ["ContentES"] = "El enorme baúl lleno de juguetes explosivos: Dirigibles Bum, Cohetes Silbadores, Carruseles Explosivos… fue testigo de un nuevo comienzo en la Juguetería ¡Pum-pum!",
            ["TextMapId"] = "PartyReward_Description_310304",
            },
        ["PartyReward_Description_320101"] = {
            ["ContentES"] = "“Atiende bien a esta clienta.”",
            ["TextMapId"] = "PartyReward_Description_320101",
            },
        ["PartyReward_Description_320102"] = {
            ["ContentES"] = "Nunca imaginaste que algo así se podría beber.",
            ["TextMapId"] = "PartyReward_Description_320102",
            },
        ["PartyReward_Description_320103"] = {
            ["ContentES"] = "Un jarabe espeso y delicioso, cuya dulzura se aferra al paladar durante mucho tiempo.",
            ["TextMapId"] = "PartyReward_Description_320103",
            },
        ["PartyReward_Description_320104"] = {
            ["ContentES"] = "Un alcohol barato, para algunos un estimulante, para otros un anestésico. Cuando brindamos, saludamos “Por el Inquebrantable, por aquellos que nunca ceden”",
            ["TextMapId"] = "PartyReward_Description_320104",
            },
        ["PartyReward_Description_330101"] = {
            ["ContentES"] = "Después de un largo día recorriendo la mansión de los Kossak, Margie y tú han reunido un verdadero tesoro. Esperemos que valga la pena el esfuerzo y el dolor de brazos.",
            ["TextMapId"] = "PartyReward_Description_330101",
            },
        ["PartyReward_Description_330102"] = {
            ["ContentES"] = "Enterradas en la oscuridad, unas partituras escritas para el pueblo de Charon permanecieron olvidadas, hasta que Margie las hizo sonar en Lago Helado, y fue entonces cuando volvieron a encontrar su verdadero propósito.",
            ["TextMapId"] = "PartyReward_Description_330102",
            },
        ["PartyReward_Description_330103"] = {
            ["ContentES"] = "Un regalo de cumpleaños pensado por un padre amoroso para su hija: muy funcional y con una pequeña sorpresa.",
            ["TextMapId"] = "PartyReward_Description_330103",
            },
        ["PartyReward_Description_330104"] = {
            ["ContentES"] = "Una bola de pelo gris, salpicada con manchas negras, evoca la imagen de una gatita con cola frondosa que camina con orgullo por la nieve.",
            ["TextMapId"] = "PartyReward_Description_330104",
            },
        ["PartyReward_Description_410101"] = {
            ["ContentES"] = "La columna “tareas diarias” siempre está repleta de nimiedades, que a veces se extienden hasta una segunda página. Así era la vida de Rhythm en la Escolta.",
            ["TextMapId"] = "PartyReward_Description_410101",
            },
        ["PartyReward_Description_410102"] = {
            ["ContentES"] = "Un álbum de recortes ordenado lleno de recortes de periódicos: limpiador, ayudante de cocina, escriba, pescador, camarero, albañil... ¿y hasta un entrenador de animales?",
            ["TextMapId"] = "PartyReward_Description_410102",
            },
        ["PartyReward_Description_410103"] = {
            ["ContentES"] = "Cada pasaje complicado está claramente marcado, con notas cuidadosas en los márgenes. Está claro que pertenece a un intérprete diligente, aunque aún no experimentado. Mira más de cerca y verás un lindo y pequeño rayo en la esquina.",
            ["TextMapId"] = "PartyReward_Description_410103",
            },
        ["PartyReward_Description_420201"] = {
            ["ContentES"] = "Olvídate de la rutina y olvídate del cansancio: ¡comienza tu merecido descanso con un capricho dulce y relajado!",
            ["TextMapId"] = "PartyReward_Description_420201",
            },
        ["PartyReward_Description_420202"] = {
            ["ContentES"] = "“Triunfo”, una bebida de alta gama añejada durante 20 años, se ha convertido en un símbolo de refinamiento y prestigio entre la élite Hiperbórea. Sin embargo, debajo del lujoso envoltorio, la amargura es difícil de ocultar.",
            ["TextMapId"] = "PartyReward_Description_420202",
            },
        ["PartyReward_Description_420203"] = {
            ["ContentES"] = "La pistola sirve como símbolo de responsabilidad, que pesa mucho sobre los hombros de un padre, y como insignia de honor que se transmite de generación en generación.",
            ["TextMapId"] = "PartyReward_Description_420203",
            },
        ["PartyReward_Description_420204"] = {
            ["ContentES"] = "A veces, las mejores ideas surgen mientras estamos duchándonos, durmiendo o tomando un té. Las acciones emprendidas en busca de tal inspiración podrían parecer un poco... excéntricas para el mundo exterior.",
            ["TextMapId"] = "PartyReward_Description_420204",
            },
        ["PartyReward_Description_430101"] = {
            ["ContentES"] = "La 13.ª Legión es un símbolo de autoridad, el vehículo de la voluntad y la violencia del emperador.",
            ["TextMapId"] = "PartyReward_Description_430101",
            },
        ["PartyReward_Description_430102"] = {
            ["ContentES"] = "El hábito es algo poderoso. Nos hace aceptar lo anormal y alejarnos aún más de la norma.",
            ["TextMapId"] = "PartyReward_Description_430102",
            },
        ["PartyReward_Description_430103"] = {
            ["ContentES"] = "Bajo la gloria de esta medalla se esconde un camino sembrado de espinas.",
            ["TextMapId"] = "PartyReward_Description_430103",
            },
        ["PartyReward_Description_510101"] = {
            ["ContentES"] = "Esta bebida clásica nació de un accidente, pero se convirtió en una bebida habitual en Atlasia por su encanto versátil. Después de generaciones de refinamiento, ha trascendido su propósito original de saciar la sed y calmar el hambre, convirtiéndose en un símbolo de nuestra búsqueda del deleite culinario.",
            ["TextMapId"] = "PartyReward_Description_510101",
            },
        ["PartyReward_Description_510102"] = {
            ["ContentES"] = "Maduradas por el tiempo y revestidas de un blanco nevado, las Torcinueces esperan tranquilamente la cosecha, ofreciendo la generosidad de la naturaleza.",
            ["TextMapId"] = "PartyReward_Description_510102",
            },
        ["PartyReward_Description_510103"] = {
            ["ContentES"] = "Jugo de bayas boreales recién exprimido, con la acidez filtrada, dejando solo una rica dulzura. ¿El secreto para hacerlo aún mejor? Compartirlo con tu mejor amiga.",
            ["TextMapId"] = "PartyReward_Description_510103",
            },
        ["PartyReward_Description_510104"] = {
            ["ContentES"] = "Una avellana por pregunta: ese es el trato que hiciste con la chica. Así que cuando tengas dudas, ¿por qué no preguntarle a la avellana mágica?",
            ["TextMapId"] = "PartyReward_Description_510104",
            },
        ["PartyReward_Description_510201"] = {
            ["ContentES"] = "No hacen falta palabras, un trago lo dice todo.",
            ["TextMapId"] = "PartyReward_Description_510201",
            },
        ["PartyReward_Description_510202"] = {
            ["ContentES"] = "Después de un arduo día de trabajo, nada mejor que una buena bebida, y no es solo por su sabor, si no por la frescura y el hecho de poder disfrutarla con amigos.",
            ["TextMapId"] = "PartyReward_Description_510202",
            },
        ["PartyReward_Description_510203"] = {
            ["ContentES"] = "Sumerge esos recuerdos insoportables en la bebida. Luego bébela de un solo trago.",
            ["TextMapId"] = "PartyReward_Description_510203",
            },
        ["PartyReward_Description_510204"] = {
            ["ContentES"] = "Todo problema tiene solución. Mientras más te preocupes, más difícil se volverá el camino por delante.",
            ["TextMapId"] = "PartyReward_Description_510204",
            },
        ["PartyReward_Description_530101"] = {
            ["ContentES"] = "Los niños se acurrucan juntos, soñando con un futuro que está más allá de su alcance.",
            ["TextMapId"] = "PartyReward_Description_530101",
            },
        ["PartyReward_Description_530102"] = {
            ["ContentES"] = "“Por favor mira el mundo a través de tus ojos para mí.”",
            ["TextMapId"] = "PartyReward_Description_530102",
            },
        ["PartyReward_Description_530103"] = {
            ["ContentES"] = "La moneda ha sido lanzada. Nadie puede predecir el resultado: cara o cruz, muerte o renacimiento.",
            ["TextMapId"] = "PartyReward_Description_530103",
            },
        ["PartyReward_Description_540101"] = {
            ["ContentES"] = "Un ramo de flores cubierto con el rocío de la mañana y destinado a visitar a los enfermos. Pero el dolor verdadero no desaparece solo por un buen gesto.",
            ["TextMapId"] = "PartyReward_Description_540101",
            },
        ["PartyReward_Description_540102"] = {
            ["ContentES"] = "Un bisturí aún manchado de sangre, testigo de una tragedia catalogada como “accidente”. Pero ella sabe que no fue un accidente. El verdadero culpable no fue una sola persona… o quizás lo fueron todos.",
            ["TextMapId"] = "PartyReward_Description_540102",
            },
        ["PartyReward_Description_540103"] = {
            ["ContentES"] = "Una grabadora de voz que conserva su determinación al momento de su partida.",
            ["TextMapId"] = "PartyReward_Description_540103",
            },
        ["PartyReward_Name_110101"] = {
            ["ContentES"] = "Granada",
            ["TextMapId"] = "PartyReward_Name_110101",
            },
        ["PartyReward_Name_110102"] = {
            ["ContentES"] = "Pluma afilada",
            ["TextMapId"] = "PartyReward_Name_110102",
            },
        ["PartyReward_Name_110103"] = {
            ["ContentES"] = "Entre hojas y ramas",
            ["TextMapId"] = "PartyReward_Name_110103",
            },
