        ["QUEST_INSPECIALQUEST_MSG"] = {
            ["ContentES"] = "Actualmente en misión especial",
            ["TextMapId"] = "QUEST_INSPECIALQUEST_MSG",
            },
        ["QuestDesc_10020101"] = {
            ["ContentES"] = "En ese fatídico día en la Isla del Purgatorio, la suerte te favoreció y viviste para ver otro día. Al despertar de nuevo, Berenica ya no estaba, dejándote en medio de un paisaje nevado desconocido.\
Una dama vestida de rojo, que se presentó como Camilla, junto con una niña llamada Nieve, te invitaron a ir con ellas a Lago Helado.\
Después de pensarlo mucho, decidiste unirse a ellas...",
            ["TextMapId"] = "QuestDesc_10020101",
            },
        ["QuestDesc_10020102"] = {
            ["ContentES"] = "En ese fatídico día en la Isla del Purgatorio, la suerte te favoreció y viviste para ver otro día. Al despertar de nuevo, Berenica ya no estaba, dejándote en medio de un paisaje nevado desconocido.\
Una dama vestida de rojo, que se presentó como Camilla, junto con una niña llamada Nieve, te invitaron a ir con ellas a Lago Helado.\
Después de pensarlo mucho, decidiste unirse a ellas...",
            ["TextMapId"] = "QuestDesc_10020102",
            },
        ["QuestDesc_10020103"] = {
            ["ContentES"] = "El vehículo volcado y la carga esparcida en el puente han atraído a los Filthoids. Repele a estos visitantes no deseados.",
            ["TextMapId"] = "QuestDesc_10020103",
            },
        ["QuestDesc_10020104"] = {
            ["ContentES"] = "Después de haber expulsado con éxito a los Filthoids, tú y Nieve continúan su viaje hacia Lago Helado.",
            ["TextMapId"] = "QuestDesc_10020104",
            },
        ["QuestDesc_10020105"] = {
            ["ContentES"] = "A pesar de un pequeño contratiempo con el guardia que verificaba los permisos de viaje, las inteligentes negociaciones de la Sra. Camilla aseguraron tu entrada a Lago Helado.",
            ["TextMapId"] = "QuestDesc_10020105",
            },
        ["QuestDesc_10020106"] = {
            ["ContentES"] = "La señorita Camilla sugiere que te alojes en la Casa de Hypnos.\
A pesar de sus inquietantes historias, decides profundizar...",
            ["TextMapId"] = "QuestDesc_10020106",
            },
        ["QuestDesc_10020107"] = {
            ["ContentES"] = "La señorita Camilla sugiere que te alojes en la Casa de Hypnos.\
A pesar de sus inquietantes historias, decides profundizar...",
            ["TextMapId"] = "QuestDesc_10020107",
            },
        ["QuestDesc_10020108"] = {
            ["ContentES"] = "Henrik, el dueño de la Casa de Hypnos, es un hombre melancólico y distante.\
Persuadido por una joven llena de energía, le ofrece a regañadientes refugio para pasar la noche.\
Es hora de dirigirte a la casa mencionada por la chica.",
            ["TextMapId"] = "QuestDesc_10020108",
            },
        ["QuestDesc_10020109"] = {
            ["ContentES"] = "Henrik, el dueño de la Casa de Hypnos, es un hombre melancólico y distante.\
Persuadido por una joven llena de energía, le ofrece a regañadientes refugio para pasar la noche.\
Es hora de dirigirte a la casa mencionada por la chica.",
            ["TextMapId"] = "QuestDesc_10020109",
            },
        ["QuestDesc_10020110"] = {
            ["ContentES"] = "Un raro momento de descanso. Es hora de poner en orden tus preguntas y la situación en cuestión.",
            ["TextMapId"] = "QuestDesc_10020110",
            },
        ["QuestDesc_10020111"] = {
            ["ContentES"] = "Tienes algunas preguntas para Psyche.",
            ["TextMapId"] = "QuestDesc_10020111",
            },
        ["QuestDesc_10020112"] = {
            ["ContentES"] = "Antes de embarcarte en tu búsqueda para encontrar Berenica, necesitas reunir algunos fondos y obtener un permiso de viaje.\
Psyche revela que “El Asfódelo”, una taberna dirigida por Camilla, ofrece una forma de ganar dinero a través de encargos sin necesidad de permisos de viaje.",
            ["TextMapId"] = "QuestDesc_10020112",
            },
        ["QuestDesc_10020201"] = {
            ["ContentES"] = "Antes de embarcarte en tu búsqueda para encontrar Berenica, necesitas reunir algunos fondos y obtener un permiso de viaje.\
Psyche revela que “El Asfódelo”, una taberna dirigida por Camilla, ofrece una forma de ganar dinero a través de encargos sin necesidad de permisos de viaje.",
            ["TextMapId"] = "QuestDesc_10020201",
            },
        ["QuestDesc_10020202"] = {
            ["ContentES"] = "Antes de embarcarte en tu búsqueda para encontrar Berenica, necesitas reunir algunos fondos y obtener un permiso de viaje.\
Psyche revela que “El Asfódelo”, una taberna dirigida por Camilla, ofrece una forma de ganar dinero a través de encargos sin necesidad de permisos de viaje.",
            ["TextMapId"] = "QuestDesc_10020202",
            },
        ["QuestDesc_10020203"] = {
            ["ContentES"] = "En la plaza fuiste testigo de una atrocidad: es lo habitual para los “Charons” con cuernos y espinas únicas.\
Para evitar meter en problemas a la señorita Camilla, quien había respondido por ti, guardaste silencio.\
Continúa hacia “El Asfódelo”.",
            ["TextMapId"] = "QuestDesc_10020203",
            },
        ["QuestDesc_10020204"] = {
            ["ContentES"] = "La chica recicladora llamada Margie se ha topado con algunas dificultades.\
Pregúntale sobre su situación.",
            ["TextMapId"] = "QuestDesc_10020204",
            },
        ["QuestDesc_10020205"] = {
            ["ContentES"] = "La chica recicladora llamada Margie se ha topado con algunas dificultades.\
Pregúntale sobre su situación.",
            ["TextMapId"] = "QuestDesc_10020205",
            },
        ["QuestDesc_10020206"] = {
            ["ContentES"] = "Un ladrón le robó a Margie, una joven recicladora.\
Ayúdala a recuperar su bolsa de dinero. No sólo para ayudarla, sino también para pasar la prueba de Camilla.",
            ["TextMapId"] = "QuestDesc_10020206",
            },
        ["QuestDesc_10020207"] = {
            ["ContentES"] = "Un ladrón le robó a Margie, una joven recicladora.\
Después de salir del Asfódelo, intenta preguntar en la plaza para ver si alguien ha visto al ladrón.",
            ["TextMapId"] = "QuestDesc_10020207",
            },
        ["QuestDesc_10020208"] = {
            ["ContentES"] = "Un anciano llamado Badi, que vive cerca de la plaza, afirma haber visto al ladrón.\
Él sugiere buscar alrededor del basurero #3.",
            ["TextMapId"] = "QuestDesc_10020208",
            },
        ["QuestDesc_10020209"] = {
            ["ContentES"] = "Cerca del basurero, descubres efectivamente huellas del ladrón; conducen hasta los tejados.\
Sube al tejado y continúa tu investigación.",
            ["TextMapId"] = "QuestDesc_10020209",
            },
        ["QuestDesc_10020210"] = {
            ["ContentES"] = "Estás en el tejado. Registra los alrededores en busca del ladrón.",
            ["TextMapId"] = "QuestDesc_10020210",
            },
        ["QuestDesc_10020211"] = {
            ["ContentES"] = "Por fin encuentras al ladrón que robó la bolsa de Margie. Tras un breve enfrentamiento, huye de repente.\
¡No hay tiempo que perder: persíguelo! Espera… algo parece extraño cerca de la boca de alcantarilla.",
            ["TextMapId"] = "QuestDesc_10020211",
            },
        ["QuestDesc_10020212"] = {
            ["ContentES"] = "Siguiendo el rastro hacia las alcantarillas, el ladrón ha dejado trampas para ralentizarte.\
Encuentra una manera de desactivar estos mecanismos y continuar la persecución.",
            ["TextMapId"] = "QuestDesc_10020212",
            },
        ["QuestDesc_10020213"] = {
            ["ContentES"] = "Has conseguido accionar los interruptores y bajar con éxito el nivel del agua.\
Es hora de reanudar la persecución.",
            ["TextMapId"] = "QuestDesc_10020213",
            },
        ["QuestDesc_10020213_1"] = {
            ["ContentES"] = "El ladrón te tendió una emboscada con una serie de trampas preparadas de antemano. Margie y Snow fueron tomadas por sorpresa y recibieron algunos golpes.\
Sigue buscando por la zona: no puede haber ido muy lejos.",
            ["TextMapId"] = "QuestDesc_10020213_1",
            },
        ["QuestDesc_10020214"] = {
            ["ContentES"] = "El ladrón utilizó un pequeño dispositivo para liberar una espesa niebla y desapareció en ella. Necesitarás una llave de repuesto para continuar la persecución.",
            ["TextMapId"] = "QuestDesc_10020214",
            },
        ["QuestDesc_10020215"] = {
            ["ContentES"] = "Por fin, has visto al ladrón de nuevo. Esta vez no se escapará.\
Derrota al ladrón y captúralo.",
            ["TextMapId"] = "QuestDesc_10020215",
            },
        ["QuestDesc_10020221"] = {
            ["ContentES"] = "Has completado el encargo de Margie. Regresa al Asfódelo para recibir tu recompensa.",
            ["TextMapId"] = "QuestDesc_10020221",
            },
        ["QuestDesc_10020222"] = {
            ["ContentES"] = "Todas los encargos para Phoxcazadores están en el tablón de anuncios del Asfódelo. Ve a comprobarlo.",
            ["TextMapId"] = "QuestDesc_10020222",
            },
        ["QuestDesc_10020223"] = {
            ["ContentES"] = "Wells te entendió mal y se avergonzó. Decidió comprarte una bebida para expresar sus disculpas...",
            ["TextMapId"] = "QuestDesc_10020223",
            },
        ["QuestDesc_10020224"] = {
            ["ContentES"] = "El sistema de Geniemons ahora está desbloqueado. Captura un Geniemon para que te ayude en tu próximo viaje.",
            ["TextMapId"] = "QuestDesc_10020224",
            },
        ["QuestDesc_10020301"] = {
            ["ContentES"] = "Henrik, dueño de la Casa de Hypnos, ha ofrecido una lucrativa recompensa a los Phoxcazadores para recuperar el Cristal estelar de la Mina de Glevumm.\
La recompensa cubre perfectamente tus gastos de viaje al sur, así que decides arriesgarte...",
            ["TextMapId"] = "QuestDesc_10020301",
            },
        ["QuestDesc_10020302"] = {
            ["ContentES"] = "Psyche decide unirse a nuestro viaje para mostrarnos el camino hacia la Mina de Glevum.\
Partimos con Psyche hacia la Mina de Glevum.",
            ["TextMapId"] = "QuestDesc_10020302",
            },
        ["QuestDesc_10020303"] = {
            ["ContentES"] = "Parece que Psyche ha tomado una decisión: va contigo en esta pequeña “aventura”.\
Partimos con Psyche hacia la Mina de Glevum.",
            ["TextMapId"] = "QuestDesc_10020303",
            },
        }
  end },
  { MinKey = "QuestDesc_10020304", MaxKey = "QuestName_10020110_2", Loader = function()
      return {
        ["QuestDesc_10020304"] = {
