            ["TextMapId"] = "RESOURCE_DESC_12136",
            },
        ["RESOURCE_DESC_12137"] = {
            ["ContentES"] = "Componente de Danza del Velo Celeste diseñado según los planos. Es de donde se disparan las balas; en cada ráfaga, el cañón y el corazón del soldado se calientan por igual.",
            ["TextMapId"] = "RESOURCE_DESC_12137",
            },
        ["RESOURCE_DESC_12138"] = {
            ["ContentES"] = "Componente de Dualidad celestial diseñado según los planos. La parte del arma que está más en próxima al portador resulta verdaderamente cómoda en la mano.",
            ["TextMapId"] = "RESOURCE_DESC_12138",
            },
        }
  end },
  { MinKey = "RESOURCE_DESC_12139", MaxKey = "RESOURCE_DESC_41027", Loader = function()
      return {
