            },
        ["RESOURCE_NAME_5210300"] = {
            ["ContentES"] = "Los similares se atraen",
            ["TextMapId"] = "RESOURCE_NAME_5210300",
            },
        ["RESOURCE_NAME_5210400"] = {
            ["ContentES"] = "¡Qué delicioso!",
            ["TextMapId"] = "RESOURCE_NAME_5210400",
            },
        ["RESOURCE_NAME_6000001"] = {
