        ["RLBlessingGroup_Desc_1"] = {
            ["ContentES"] = "Mejoras de armas cuerpo a cuerpo",
            ["TextMapId"] = "RLBlessingGroup_Desc_1",
            },
        ["RLBlessingGroup_Desc_101"] = {
            ["ContentES"] = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Prob. CRIT y + <Highlight>15%</> de Daño CRIT para armas cuerpo a cuerpo.\
Infligir daño con armas cuerpo a cuerpo tiene un <Highlight>10%</> de probabilidad de aplicar 1 acumulación de [Llama fundida].",
            ["TextMapId"] = "RLBlessingGroup_Desc_101",
            },
        ["RLBlessingGroup_Desc_102"] = {
            ["ContentES"] = "[Llama fundida] inflige un <Highlight>35%</> del ATQ del personaje como daño periódico cada <Highlight>1</>s.",
            ["TextMapId"] = "RLBlessingGroup_Desc_102",
            },
        ["RLBlessingGroup_Desc_103"] = {
            ["ContentES"] = "Extiende la duración de [Llama fundida] a <Highlight>10</> s. Ahora se acumula hasta <Highlight>20</> veces.",
            ["TextMapId"] = "RLBlessingGroup_Desc_103",
            },
        ["RLBlessingGroup_Desc_104"] = {
            ["ContentES"] = "Los objetivos afectados con [Llama fundida] sufren un golpe de [Sable de llama fundida] cada <Highlight>5</> s. Infligir daño con armas cuerpo a cuerpo tiene un <Highlight>10%</> de probabilidad de activar un [Sable de llama fundida] adicional.",
            ["TextMapId"] = "RLBlessingGroup_Desc_104",
            },
        ["RLBlessingGroup_Desc_2"] = {
            ["ContentES"] = "Mejoras de armas a distancia",
            ["TextMapId"] = "RLBlessingGroup_Desc_2",
            },
        ["RLBlessingGroup_Desc_201"] = {
            ["ContentES"] = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Prob. CRIT y + <Highlight>15%</> de Daño CRIT para armas a distancia.\
Aumenta el Rango de Recogida Automática. Otorga inmunidad al Aturdimiento durante <Highlight>3</> s después de recoger botín.",
            ["TextMapId"] = "RLBlessingGroup_Desc_201",
            },
        ["RLBlessingGroup_Desc_202"] = {
            ["ContentES"] = "Infligir daño con cualquier arma a distancia activa [Luna marina] y genera <Highlight>3</> [Mini Lunas marinas] adicionales (máximo una vez cada <Highlight>10</> s).",
            ["TextMapId"] = "RLBlessingGroup_Desc_202",
            },
        ["RLBlessingGroup_Desc_203"] = {
            ["ContentES"] = "Al recolectar una [Mini Luna marina] se obtiene 1 [Luna velada].",
            ["TextMapId"] = "RLBlessingGroup_Desc_203",
            },
        ["RLBlessingGroup_Desc_204"] = {
            ["ContentES"] = "Al consumir [Luna velada] se disparan <Highlight>3</> [Aguijones] en una dispersión en forma de abanico. Recoger botín otorga 1 acumulación de [Deriva fantasma].",
            ["TextMapId"] = "RLBlessingGroup_Desc_204",
            },
        }
  end },
