            },
        ["RLBlessing_Desc_114"] = {
            ["ContentES"] = "Las armas cuerpo a cuerpo infligen daño adicional equivalente al <Highlight>$1</> del ATQ del personaje a los objetivos afectados por más de <Highlight>$2</> acumulaciones de [Llama fundida].",
            ["TextMapId"] = "RLBlessing_Desc_114",
            },
        ["RLBlessing_Desc_115"] = {
