            ["TextMapId"] = "RLBlessing_Desc_701",
            },
        ["RLBlessing_Desc_702"] = {
            ["ContentES"] = "Aumenta la recuperación automática de Cordura en <Highlight>$2</> cuando los PV están por debajo del <Highlight>100%</> y en <Highlight>$1</> cuando los PV están al <Highlight>100%</>.",
