        ["RLTreasureGroup_Desc_101"] = {
            ["ContentES"] = "Con los <Highlight>2</> Artefactos de [Caballero guardián] recolectados, tu personaje gana puntos de Escudo Ultra equivalente al <Highlight>10%</> de sus PV Máx. cada <Highlight>10</> s mientras esté dentro de [Abisoides].",
            ["TextMapId"] = "RLTreasureGroup_Desc_101",
            },
        ["RLTreasureGroup_Desc_102"] = {
            ["ContentES"] = "Con los <Highlight>3</> Artefactos del [Pacto del Dios de la Abundancia] recolectados, tu personaje obtiene un aumento de Daño del <Highlight>10%</> por cada <Highlight>100</> Brasas que posea.\
Si las Brasas están por debajo de <Highlight>200</>, reduce el Daño Recibido en <Highlight>30%</>.",
            ["TextMapId"] = "RLTreasureGroup_Desc_102",
            },
        ["RLTreasureGroup_Desc_103"] = {
            ["ContentES"] = "Con los <Highlight>4</> Artefactos de [Cuatro sellos elementales] recolectados, establece la Probabilidad de Activación al <Highlight>50%</> y el multiplicador de daño al <Highlight>100%</>, y convierte todo el daño en Daño Puro.",
            ["TextMapId"] = "RLTreasureGroup_Desc_103",
            },
        ["RLTreasureGroup_Desc_104"] = {
            ["ContentES"] = "Con los <Highlight>4</> Artefactos de [Caballero penitente] recolectados, elimina la penalización y aumenta la bonificación de daño total al <Highlight>400%</>.",
            ["TextMapId"] = "RLTreasureGroup_Desc_104",
            },
        ["RLTreasureGroup_Desc_105"] = {
            ["ContentES"] = "Con los <Highlight>2</> Artefactos de [Hechicera desolada] recolectados, aumenta la reducción de [Postura] en un <Highlight>100%</> y el Daño Infligido a los enemigos bajo [Retribución de Ask] en un <Highlight>100%</>",
            ["TextMapId"] = "RLTreasureGroup_Desc_105",
            },
