        ["RLTreasure_Desc_10206"] = {
            ["ContentES"] = "El Daño de Habilidad ignora <Highlight>$1</> de la DEF del objetivo. Por cada tipo de Mecha poseído, este efecto se reduce en <Highlight>$3</>, hasta un mínimo de <Highlight>$2</>.",
