        ["RLTreasure_Desc_15101"] = {
            ["ContentES"] = "Cuando la [Postura] del enemigo está por encima de <Highlight>$1</>, tu personaje recupera <Highlight>$2</> de Cordura al infligir daño. Tiempo de enfriamiento: <Highlight>$3</> s.",
            ["TextMapId"] = "RLTreasure_Desc_15101",
