        ["RegionReputation_EntrustContent_01"] = {
            ["ContentES"] = "“En Los Asfódelos hay unos recién llegados que no creen en tu reputación. Dicen que todo es puro cuento y quieren que lo demuestres con botín real...”",
            ["TextMapId"] = "RegionReputation_EntrustContent_01",
            },
        ["RegionReputation_EntrustContent_02"] = {
            ["ContentES"] = "“Últimamente en Los Asfódelos han surgido negocios que requieren materiales especiales. Si tienes tiempo, échame una mano y recibirás tu recompensa”.",
            ["TextMapId"] = "RegionReputation_EntrustContent_02",
            },
        ["RegionReputation_EntrustContent_03"] = {
            ["ContentES"] = "“Un Phoxcazador te propone una apuesta: dice que no podrás conseguirlos. ¿Vas a aceptar el desafío?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_03",
            },
        ["RegionReputation_EntrustContent_04"] = {
            ["ContentES"] = "“Con lo mucho que viajas, seguro que has juntado muchas cosas interesantes. ¿Me venderías algunas? Estoy pensando en montar un pequeño negocio...”",
            ["TextMapId"] = "RegionReputation_EntrustContent_04",
            },
        ["RegionReputation_EntrustContent_05"] = {
            ["ContentES"] = "“Los señores de la ciudad interior quieren conocer los productos del exterior, pero ya sabes... los Filthoids son peligrosos. Por eso solo podemos contar contigo”.",
            ["TextMapId"] = "RegionReputation_EntrustContent_05",
            },
        ["RegionReputation_EntrustContent_06"] = {
            ["ContentES"] = "“Uuuh... mi carga fue volcada por los Filthoids fuera de la ciudad y perdí varias cosas. ¿Podrías ayudarme a recuperarlas? Porfa, porfa, porfa...”",
            ["TextMapId"] = "RegionReputation_EntrustContent_06",
            },
        ["RegionReputation_EntrustContent_07"] = {
            ["ContentES"] = "“Las investigaciones indican que las Cuñas Demoníacas contienen fluctuaciones de energía que antes había pasado por alto. Me gustaría que me dieras algunas...”",
            ["TextMapId"] = "RegionReputation_EntrustContent_07",
            },
        ["RegionReputation_EntrustContent_08"] = {
            ["ContentES"] = "“Dicen que con las Cuñas Demoníacas uno se vuelve mucho más fuerte. Quiero estudiar cómo funcionan, ¿me ayudarías a conseguir algunas?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_08",
            },
        ["RegionReputation_EntrustContent_09"] = {
            ["ContentES"] = "“Voy a encerrarme para intentar reproducir una Cuña Demoníaca. ¿Puedes traerme algunas muestras?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_09",
            },
        ["RegionReputation_EntrustContent_10"] = {
            ["ContentES"] = "“¿Eh? ¿Que aquí hay un elfo del basurero que cumple deseos si se los pides con sinceridad? Es broma... pero sí necesito estos suministros”.",
            ["TextMapId"] = "RegionReputation_EntrustContent_10",
            },
        ["RegionReputation_EntrustContent_11"] = {
            ["ContentES"] = "“Hace mucho frío y en Lago Glacial los necesitamos para sobrevivir al invierno. ¡Cuento contigo!”",
            ["TextMapId"] = "RegionReputation_EntrustContent_11",
            },
        ["RegionReputation_EntrustContent_12"] = {
            ["ContentES"] = "“Esta vez es algo personal. Quiero comprar algo a ese comerciante extranjero itinerante, pero... je, je, otra vez necesito tu ayuda”.",
            ["TextMapId"] = "RegionReputation_EntrustContent_12",
            },
        ["RegionReputation_EntrustContent_13"] = {
            ["ContentES"] = "“Estos productos están muy solicitados, pero últimamente los Bi’an Sombríos han estado causando estragos en las rutas comerciales. Si nos echas la mano, te lo vamos a agradecer de corazón”.",
            ["TextMapId"] = "RegionReputation_EntrustContent_13",
            },
        ["RegionReputation_EntrustContent_14"] = {
            ["ContentES"] = "“Dicen que tú puedes plantarle cara {性别: solo|sola} a un Bi’an Sombrío... ¿Será cierto? ¿Te animas a demostrarlo?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_14",
            },
        ["RegionReputation_EntrustContent_15"] = {
            ["ContentES"] = "“Esas criaturas envueltas en humo negro parecen peligrosas, pero los objetos que cargan me despiertan mucha curiosidad. ¿Podrías traerme alguno para examinarlo?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_15",
            },
        ["RegionReputation_EntrustContent_16"] = {
            ["ContentES"] = "“Según Nieve, siempre encuentran estas cosas durante sus aventuras, y muchas ni siquiera las usan. Si puedes, ¿me darías algunas?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_16",
            },
        ["RegionReputation_EntrustContent_17"] = {
            ["ContentES"] = "“La Reina Demonio dice que eres increíblemente fuerte en combate... Yo... yo le tengo miedo a esos Bi’an Sombríos que merodean afuera. ¿Podrías ayudarme?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_17",
            },
        ["RegionReputation_EntrustContent_18"] = {
            ["ContentES"] = "“¡Recibí un encargo que vino a buscarme directamente! Pero no tengo suficiente mercancía... ¿podrías echarme la mano?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_18",
            },
        ["RegionReputation_EntrustContent_19"] = {
            ["ContentES"] = "“¿Oh? ¿La misteriosa tecnología de Hiperbórea? ¿Cómo se compara con nuestra técnica de la Titiritería Mecánica? ¿Por qué no traes algunas para que las analicemos? Tal vez logremos crear algo aún más poderoso”.",
            ["TextMapId"] = "RegionReputation_EntrustContent_19",
            },
        ["RegionReputation_EntrustContent_20"] = {
            ["ContentES"] = "“Tráeme más Cuñas Demoníacas, estoy a punto de descifrar su principio”.",
            ["TextMapId"] = "RegionReputation_EntrustContent_20",
            },
        ["RegionReputation_EntrustContent_21"] = {
            ["ContentES"] = "“¿Las Cuñas Demoníacas solo refuerzan a los del Clan Dragón? Si las combináramos con la técnica de la Titiritería Mecánica... ¿qué poder podría desatarse?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_21",
            },
        ["RegionReputation_EntrustContent_22"] = {
            ["ContentES"] = "“No te preocupes. Si hoy me ayudas, llegará el día en que yo te lo recompense”.",
            ["TextMapId"] = "RegionReputation_EntrustContent_22",
            },
        ["RegionReputation_EntrustContent_23"] = {
            ["ContentES"] = "“Últimamente los miembros de la Asociación de Arqueología me han solicitado un lote de suministros. ¿Tienes algo de tiempo para ayudarnos?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_23",
            },
        ["RegionReputation_EntrustContent_24"] = {
            ["ContentES"] = "“Si hasta la comerciante Zhiliu te aprecia tanto, seguro que tienes un gran talento. No vas a rechazar esta oportunidad, ¿verdad?”",
            ["TextMapId"] = "RegionReputation_EntrustContent_24",
            },
