        ["RegionReputation_IPDes"] = {
            ["ContentES"] = "Alzado por miles de manos, voces sin rostro claman tu nombre. Ciñen la corona sobre tu frente; eres el único digno de llevarla.",
            ["TextMapId"] = "RegionReputation_IPDes",
            },
