        ["SKILL_310301_NAME"] = {
            ["ContentES"] = "Pequeño Bum",
            ["TextMapId"] = "SKILL_310301_NAME",
            },
        ["SKILL_310302_DESC"] = {
            ["ContentES"] = "Genera [Laboratorio de Pesadilla] alrededor de Yale y Oliver. Usar la habilidad de nuevo puede cerrar [Laboratorio de Pesadilla] con antelación.",
            ["TextMapId"] = "SKILL_310302_DESC",
