            },
        ["SKILL_410103_DESC"] = {
            ["ContentES"] = "Al consumir Cordura, convierte un porcentaje de la Cordura consumida en [Energía Eléctrica]. El límite superior de [Energía Eléctrica] es igual a la Cordura Máx.",
            ["TextMapId"] = "SKILL_410103_DESC",
            },
