            },
        ["SKILL_420203_DESC"] = {
            ["ContentES"] = "Cuando Randy otorga con éxito un Escudo Ultra a un compañero, aplica una acumulación que aumenta su DEF según la DEF de Randy, hasta un máximo de 10 acumulaciones.",
            ["TextMapId"] = "SKILL_420203_DESC",
