            ["ContentES"] = "Invocador de Tormentas",
            ["TextMapId"] = "SKILL_430102_NAME",
            },
        ["SKILL_430103_DESC"] = {
            ["ContentES"] = "Cuando el daño infligido activa un Efecto Adicional, Sibylle obtiene ciertos puntos de [Poder del Trueno], hasta un máximo de 300 puntos. [Conquistador Divino] e [Invocador de Tormentas] pueden potenciarse consumiendo puntos de [Poder del Trueno].",
            ["TextMapId"] = "SKILL_430103_DESC",
