            ["TextMapId"] = "SKILL_510102_DESC",
            },
        ["SKILL_510102_NAME"] = {
            ["ContentES"] = "Barriga llena, manos llenas",
            ["TextMapId"] = "SKILL_510102_NAME",
            },
        ["SKILL_510103_DESC"] = {
            ["ContentES"] = "Obtiene 1 acumulación de [Peso Pesado] por cada segundo que se mantiene en movimiento, hasta un máximo de 10 acumulaciones. [Peso Pesado]: aumenta el daño infligido y reduce el daño recibido.",
            ["TextMapId"] = "SKILL_510103_DESC",
            },
        ["SKILL_510103_NAME"] = {
            ["ContentES"] = "¡A por todas, Comisarias!",
