            },
        ["SKILL_510104_NAME"] = {
            ["ContentES"] = "Suministros de Combate",
            ["TextMapId"] = "SKILL_510104_NAME",
            },
        ["SKILL_510191_DESC"] = {
            ["ContentES"] = "<H>[Disponible solo al desplegarse como Compañero de combate]</>\
