        ["SKILL_530103_NAME"] = {
            ["ContentES"] = "Resplandor Ámbar",
            ["TextMapId"] = "SKILL_530103_NAME",
            },
        ["SKILL_530104_DESC"] = {
            ["ContentES"] = "Al usar [Eclosión Fluorescente], si el porcentaje de PV es mayor o igual al 75%, obtiene [Efímero como el Rocío Matutino]: al calcular Moral y Tenacidad, el porcentaje de PV se considera forzosamente como 1%. Este efecto solo puede activarse una vez cada 120 s.",
