        ["UIGuide_FangShu_3_Phone"] = {
            ["ContentES"] = "ras invocar el Nexo mecánico, pulsa el botón para escanear los mecanismos interactivos cercanos.",
            ["TextMapId"] = "UIGuide_FangShu_3_Phone",
            },
        ["UIGuide_FangShu_4"] = {
            ["ContentES"] = "Después de invocar el Nexo mecánico, abre de nuevo la Mochila táctica y selecciona el Nexo mecánico para recuperarlo. Una vez retirado, los ataques a distancia y las habilidades de Geniemon estarán nuevamente disponibles.",
            ["TextMapId"] = "UIGuide_FangShu_4",
            },
        ["UIGuide_Feina_1"] = {
            ["ContentES"] = "En este cuento inconcluso, todo está en escala de grises. Haz clic en &Fire& para pintar el mundo con <H>Pigmento Tejesueños</> y darle color al relato.",
            ["TextMapId"] = "UIGuide_Feina_1",
            },
        ["UIGuide_Feina_10"] = {
            ["ContentES"] = "Observa el <H>entorno</> de cada gema y píntala con el color correcto para encender su luz y disipar las nieblas.",
            ["TextMapId"] = "UIGuide_Feina_10",
            },
        ["UIGuide_Feina_11"] = {
            ["ContentES"] = "Absorber la energía de una gema forma un aura protectora alrededor del pequeño Ruiseñor, protegiéndolo de las nieblas. El aura se desvanece con el tiempo, ilumina gemas rápidamente para renovar su fuerza.",
            ["TextMapId"] = "UIGuide_Feina_11",
            },
        ["UIGuide_Feina_12"] = {
            ["ContentES"] = "Golpea un disco grabado con pigmento <H>del color correspondiente</> para romperlo y abrir el camino.",
            ["TextMapId"] = "UIGuide_Feina_12",
            },
        ["UIGuide_Feina_1_Phone"] = {
            ["ContentES"] = "En este cuento inconcluso, todo está en escala de grises. Pulsa para pintar el mundo con <H>Pigmento Tejesueños</> y darle color al relato.",
            ["TextMapId"] = "UIGuide_Feina_1_Phone",
            },
        ["UIGuide_Feina_2"] = {
            ["ContentES"] = "<H>Plumas blancas</> están esparcidas por el reino de cuento. Reúne suficientes para obtener recompensas extra.",
            ["TextMapId"] = "UIGuide_Feina_2",
            },
        ["UIGuide_Feina_3"] = {
            ["ContentES"] = "Algunos dispositivos solo pueden activarse con ciertos colores. Haz clic en &ChargeBullet& para cambiar entre pigmentos.",
            ["TextMapId"] = "UIGuide_Feina_3",
            },
        ["UIGuide_Feina_3_Gamepad"] = {
            ["ContentES"] = "Algunos dispositivos solo pueden activarse con un color específico. Presiona &GamepadUseSkill& + &Fire& para alternar entre diferentes pigmentos.",
            ["TextMapId"] = "UIGuide_Feina_3_Gamepad",
            },
        ["UIGuide_Feina_3_Phone"] = {
            ["ContentES"] = "Algunos dispositivos solo pueden activarse con ciertos colores. Pulsa el botón para cambiar entre pigmentos.",
            ["TextMapId"] = "UIGuide_Feina_3_Phone",
            },
        ["UIGuide_Feina_4"] = {
            ["ContentES"] = "Algunas flores permanecen sin color. Observa flores cercanas de <H>la misma forma</> y píntalas con el color correspondiente.",
            ["TextMapId"] = "UIGuide_Feina_4",
            },
        ["UIGuide_Feina_5"] = {
            ["ContentES"] = "Algunas flores perderán su color tras un tiempo. <H>Píntalas todas correctamente a tiempo</> para activar el mecanismo.",
            ["TextMapId"] = "UIGuide_Feina_5",
            },
        ["UIGuide_Feina_6"] = {
            ["ContentES"] = "Aplica un pigment a la palangana para que emita luz mágica del mismo color. Observa el entorno y usa <H>el color correcto</> para activar el mecanismo.",
            ["TextMapId"] = "UIGuide_Feina_6",
            },
        ["UIGuide_Feina_7"] = {
            ["ContentES"] = "Sigue el brillo de la gema y <H>pinta todas las espinas con el color correcto</> para despejar las ramas entrelazadas.",
            ["TextMapId"] = "UIGuide_Feina_7",
            },
        ["UIGuide_Feina_8"] = {
            ["ContentES"] = "Una vez que todas las espinas estén coloreadas, el pequeño Ruiseñor usará el poder de la gema para ayudar a Fina a abrir el camino.",
            ["TextMapId"] = "UIGuide_Feina_8",
            },
        ["UIGuide_Feina_9"] = {
            ["ContentES"] = "Nieblas peligrosas invaden el bosque. Si permaneces demasiado tiempo, Fina perderá el rumbo.",
            ["TextMapId"] = "UIGuide_Feina_9",
            },
        ["UIGuide_FenZuSai_1"] = {
            ["ContentES"] = "Durante la Fase de grupos, los Phoxcazadores se enfrentan a oleadas de enemigos <H>mucho más peligrosos de lo habitual</>.",
            ["TextMapId"] = "UIGuide_FenZuSai_1",
            },
        ["UIGuide_FenZuSai_2"] = {
            ["ContentES"] = "Derrotar el número requerido de enemigos dentro del tiempo establecido permite superar la Fase de grupos.",
            ["TextMapId"] = "UIGuide_FenZuSai_2",
            },
        ["UIGuide_FenZuSai_3"] = {
            ["ContentES"] = "Los Phoxcazadores obtienen puntos de clasificación según el número de enemigos derrotados y el tiempo restante.",
            ["TextMapId"] = "UIGuide_FenZuSai_3",
            },
        ["UIGuide_FireMechanism"] = {
            ["ContentES"] = "Las <H>Trampas de llamas</> se <H>activarán</> al ser atacadas, infligiendo daño a <H>todos los objetivos</> que las atraviesen. Algunas <H>Trampas de llamas</> infligen daño más alto, pero requieren más tiempo de recarga.",
            ["TextMapId"] = "UIGuide_FireMechanism",
            },
        ["UIGuide_Fish_01"] = {
            ["ContentES"] = "Una vez que hayas lanzado la línea, espera a que el botón del carrete parpadee, eso significa que un pez ha mordido el anzuelo. Recoge la línea rápidamente antes de que se escape.",
            ["TextMapId"] = "UIGuide_Fish_01",
            },
        ["UIGuide_Fish_02"] = {
            ["ContentES"] = "Durante la recogida, mantén la vista en el indicador a la derecha. Mantén presionado el botón del carrete para aplicar tensión, alinea el indicador con la marca del pez y sostén firme hasta que la captura sea tuya.",
            ["TextMapId"] = "UIGuide_Fish_02",
            },
        ["UIGuide_Fish_03"] = {
            ["ContentES"] = "Atrapar una presa grande puede activar la <H>Oportunidad de Pescar peces más grandes</>. Usa tu captura actual como cebo y lanza de nuevo, podrías conseguir un premio aún más raro.",
            ["TextMapId"] = "UIGuide_Fish_03",
            },
        ["UIGuide_Fish_04"] = {
            ["ContentES"] = "Cuando pescas con un Geniemon con el rasgo “En paz”, la recogida es automática.",
            ["TextMapId"] = "UIGuide_Fish_04",
            },
        ["UIGuide_Fish_05"] = {
            ["ContentES"] = "Algunas especies solo aparecen en momentos específicos. Puedes cambiar la hora actual desde la interfaz de <H>Ciclo de tiempo</>.",
            ["TextMapId"] = "UIGuide_Fish_05",
            },
        ["UIGuide_Fish_SubTitle_1"] = {
            ["ContentES"] = "Lanzar y recoger",
            ["TextMapId"] = "UIGuide_Fish_SubTitle_1",
            },
        ["UIGuide_Fish_SubTitle_2"] = {
            ["ContentES"] = "Combate de carrete",
            ["TextMapId"] = "UIGuide_Fish_SubTitle_2",
            },
        ["UIGuide_Fish_SubTitle_3"] = {
            ["ContentES"] = "Pescar peces más grandes",
            ["TextMapId"] = "UIGuide_Fish_SubTitle_3",
            },
        ["UIGuide_Fish_SubTitle_4"] = {
            ["ContentES"] = "Pesca con Geniemons",
            ["TextMapId"] = "UIGuide_Fish_SubTitle_4",
            },
        ["UIGuide_Fish_SubTitle_5"] = {
            ["ContentES"] = "Los peces pican tanto de día como de noche",
            ["TextMapId"] = "UIGuide_Fish_SubTitle_5",
            },
        ["UIGuide_Fish_Title"] = {
            ["ContentES"] = "Hora de una emocionante sesión de pesca.",
            ["TextMapId"] = "UIGuide_Fish_Title",
            },
        ["UIGuide_Fort_1_PC"] = {
            ["ContentES"] = "Acércate a la torreta 4 y presiona &Interactive& para activarla. La torreta 4 está equipada con <H>Proyectiles de Alta Explosividad</> y <H>Disparos de Alta Cadencia</>.",
            ["TextMapId"] = "UIGuide_Fort_1_PC",
            },
        ["UIGuide_Fort_1_Phone"] = {
            ["ContentES"] = "Acércate a la torreta 4 e <H>interactúa</> para activarla. La torreta 4 está equipada con <H>Proyectiles de Alta Explosividad</> y <H>Disparos de Alta Cadencia</>.",
            ["TextMapId"] = "UIGuide_Fort_1_Phone",
            },
        ["UIGuide_Fort_2"] = {
            ["ContentES"] = "Los <H>Proyectiles de Alta Explosividad</> generan daño de área pero tienen un <H>mayor tiempo de recarga</>. Los <H>Disparos de Alta Cadencia</> infligen daño acelerado a un solo objetivo pero causan <H>sobrecalentamiento</> luego de una cierta cantidad de disparos, <H>impidiendo seguir disparando</> temporalmente.",
            ["TextMapId"] = "UIGuide_Fort_2",
            },
        ["UIGuide_FuWen_1"] = {
            ["ContentES"] = "Runa de Taixu flotan en el aire de Huaxu. Usa la función Atracción del Nexo Mecánico para recogerlas.",
            ["TextMapId"] = "UIGuide_FuWen_1",
            },
        ["UIGuide_FuWen_2"] = {
            ["ContentES"] = "Las Runas de Taixu se pueden intercambiar por recompensas en la tienda de Huevos de la Suerte de Luno, la carpa.",
            ["TextMapId"] = "UIGuide_FuWen_2",
            },
        ["UIGuide_HardBoss_01"] = {
            ["ContentES"] = "Derrotar a los jefes de ciertas misiones principales desbloqueará los desafíos de <H>Ecos nocturnos</> correspondientes.",
            ["TextMapId"] = "UIGuide_HardBoss_01",
            },
        ["UIGuide_HardBoss_02"] = {
            ["ContentES"] = "Los jefes que se encuentran en los desafíos Ecos nocturnos son mucho más poderosos. Puedes obtener recompensas hasta <H>5 veces por semana</>.",
            ["TextMapId"] = "UIGuide_HardBoss_02",
            },
        ["UIGuide_Hook_PC"] = {
            ["ContentES"] = "Los puntos de enganche están dispersos por el mundo. Presiona &Interactive& para lanzar el gancho y desplazarte más rápido.",
            ["TextMapId"] = "UIGuide_Hook_PC",
            },
        ["UIGuide_Hook_Phone"] = {
            ["ContentES"] = "Los puntos de enganche están dispersos por el mundo. Pulsa el botón para lanzar el gancho y viajar más rápido.",
            ["TextMapId"] = "UIGuide_Hook_Phone",
            },
        ["UIGuide_HuaBan_1"] = {
            ["ContentES"] = "Usa la función Atracción del Nexo Mecánico para dispersar los pétalos danzantes y revelar los Wishen ocultos.",
            ["TextMapId"] = "UIGuide_HuaBan_1",
            },
        ["UIGuide_HuaBao_1"] = {
            ["ContentES"] = "Algunos brotes, corrompidos por el <H>Polvo corrompido</>, contaminan continuamente su entorno.",
            ["TextMapId"] = "UIGuide_HuaBao_1",
            },
        ["UIGuide_HuaBao_2"] = {
            ["ContentES"] = "Destruye todos los grupos de brotes contaminados dentro del tiempo límite permite purificar la zona.",
            ["TextMapId"] = "UIGuide_HuaBao_2",
            },
        ["UIGuide_HuaRui_1"] = {
            ["ContentES"] = "Un Corazón de flor contaminada contamina continuamente su entorno.",
            ["TextMapId"] = "UIGuide_HuaRui_1",
            },
        ["UIGuide_HuaRui_2"] = {
            ["ContentES"] = "Ataca un Corazón de flor contaminada con armas a distancia o habilidades de Wishen hace que sus pétalos se cierren y atrae a los Filthoids.",
            ["TextMapId"] = "UIGuide_HuaRui_2",
            },
        ["UIGuide_HuaRui_3"] = {
            ["ContentES"] = "Una vez eliminados todos los Filthoids, los pétalos se abren nuevamente, exponiendo el corazón. Golpearlo con una habilidad de Wishen destruye el Corazón de flor contaminada y purifica la zona.",
            ["TextMapId"] = "UIGuide_HuaRui_3",
            },
        ["UIGuide_HuiYu_1"] = {
            ["ContentES"] = "Golpea un Jade luminoso con una habilidad de Wishen lo ilumina.",
            ["TextMapId"] = "UIGuide_HuiYu_1",
            },
        ["UIGuide_HuiYu_2"] = {
            ["ContentES"] = "Ilumina un grupo completo de Jades luminosos dentro del tiempo límite desbloquea un cofre y permite obtener sus recompensas.",
            ["TextMapId"] = "UIGuide_HuiYu_2",
            },
        ["UIGuide_ImpressionCheck_1"] = {
            ["ContentES"] = "Ocasionalmente, Pruebas de impresión se activan durante Misiones secundarias y diálogos de PNJ. Superar con éxito estas pruebas avanza el diálogo y otorga recompensas. Obtén puntos de Impresión en las 5 dimensiones para mejorar tus chances de superar estas pruebas.",
            ["TextMapId"] = "UIGuide_ImpressionCheck_1",
            },
        ["UIGuide_ImpressionCheck_2"] = {
            ["ContentES"] = "Si no logras superar una Prueba de impresión, aún puedes utilizar dados para intentarlo de nuevo. Los dados pueden ser obtenidos a través de Misiones secundarias o forjados por Luno, la herrera.",
            ["TextMapId"] = "UIGuide_ImpressionCheck_2",
            },
        ["UIGuide_ImpressionShop_1"] = {
            ["ContentES"] = "La tienda de Lunoeggy ofrece una gran selección de objetos valiosos.",
            ["TextMapId"] = "UIGuide_ImpressionShop_1",
            },
        ["UIGuide_ImpressionShop_2"] = {
            ["ContentES"] = "Completa las Pruebas de impresión designadas de Lunoeggy para obtener generosas recompensas.",
            ["TextMapId"] = "UIGuide_ImpressionShop_2",
            },
        ["UIGuide_ImpressionSystem_1"] = {
            ["ContentES"] = "Tus acciones en una región influyen continuamente en las <H>Impresiones</> que los locales tienen de ti.",
            ["TextMapId"] = "UIGuide_ImpressionSystem_1",
            },
        ["UIGuide_ImpressionSystem_2"] = {
            ["ContentES"] = "En misiones principales, misiones secundarias y diálogos de PNJ, ciertas <H>decisiones</> afectarán tu imagen social, que será reflejada a través de un sistema de evaluación compuesto por 5 dimensiones: Beneficio, Moralidad, Sabiduría, Empatía y Caos.",
            ["TextMapId"] = "UIGuide_ImpressionSystem_2",
            },
        ["UIGuide_ImpressionSystem_3"] = {
            ["ContentES"] = "<H>Lunoeggy</> admira a aquellos con personalidad. Una vez que hayas construido una sólida reputación, con suficiente puntos de Impresión, podrás retar a <H>Lunoeggy</> en la ciudad a un juego de dados por una oportunidad de ganar las <H>recompensas de Lunoeggy</>.",
            ["TextMapId"] = "UIGuide_ImpressionSystem_3",
            },
        ["UIGuide_JiGuanZhen_1"] = {
            ["ContentES"] = "Al golpear ciertas <H>Estela de la Iluminación</>, se revela un camino formado por losas mecánicas.",
            ["TextMapId"] = "UIGuide_JiGuanZhen_1",
            },
        ["UIGuide_JiGuanZhen_2"] = {
            ["ContentES"] = "Al pisar la losa correcta, aparecen patrones dorados. Pisa todas las losas en el orden correcto para desbloquear la siguiente Estela de la Iluminación.",
            ["TextMapId"] = "UIGuide_JiGuanZhen_2",
            },
        ["UIGuide_JiGuanZhen_3"] = {
            ["ContentES"] = "Al pisar una losa incorrecta, serás enviado de regreso al inicio y se reinicia la matriz del rompecabezas.",
            ["TextMapId"] = "UIGuide_JiGuanZhen_3",
            },
        ["UIGuide_JiaSu_1"] = {
            ["ContentES"] = "Toca una Runa de aceleración aumenta considerablemente la velocidad de movimiento y la distancia del Salto Espiral.",
            ["TextMapId"] = "UIGuide_JiaSu_1",
            },
        ["UIGuide_JuYuan_1"] = {
            ["ContentES"] = "Una vez finalizado el <H>Teatro Especial de Luno</>, puedes inscribirte en el evento con la Directora Putsch en el <H>Teatro Galea</>.",
            ["TextMapId"] = "UIGuide_JuYuan_1",
            },
        ["UIGuide_JuYuan_2"] = {
            ["ContentES"] = "El <H>Teatro Galea</> organiza el <H>Baile de Luno</> cada treinta minutos. Sigue las indicaciones de los Lunarios, realiza los movimientos correctos y gana recompensas: ¡cuanto más precisos sean tus movimientos, mayores serán las recompensas!",
            ["TextMapId"] = "UIGuide_JuYuan_2",
            },
        ["UIGuide_JuYuan_3"] = {
            ["ContentES"] = "Dona recursos a la Directora Putsch para ayudar a reconstruir el teatro y obtener recompensas.",
            ["TextMapId"] = "UIGuide_JuYuan_3",
            },
        ["UIGuide_LayeredMap_1"] = {
            ["ContentES"] = "Algunas áreas poseen estructuras multinivel, lo que permite cambiar entre distintos niveles del mapa para una navegación más sencilla.",
            ["TextMapId"] = "UIGuide_LayeredMap_1",
            },
        ["UIGuide_LayeredMap_2"] = {
            ["ContentES"] = "Colocar y seguir marcadores en el mapa facilita la exploración. Para quitar marcadores que ya no necesitas, simplemente selecciónalos de nuevo.",
            ["TextMapId"] = "UIGuide_LayeredMap_2",
            },
        ["UIGuide_LockMonster_PC"] = {
            ["ContentES"] = "Apunta al <H>jefe</> y presiona &LockMonster& para fijar el objetivo; presiona de nuevo para cancelar.",
            ["TextMapId"] = "UIGuide_LockMonster_PC",
            },
        ["UIGuide_LockMonster_Phone"] = {
            ["ContentES"] = "Apunta al <H>jefe</> y presiona el botón para fijar el objetivo; presiona de nuevo para cancelar.",
            ["TextMapId"] = "UIGuide_LockMonster_Phone",
            },
        ["UIGuide_LongLin_1"] = {
            ["ContentES"] = "Cuando la base de una Escama de Zhuyin está cubierta por Polvo corrompido, no puede recolectarse directamente.",
            ["TextMapId"] = "UIGuide_LongLin_1",
            },
        ["UIGuide_LongLin_2"] = {
            ["ContentES"] = "Utiliza la función Atracción del Nexo Mecánico para disipar el <H>Polvo corrompido</>.",
            ["TextMapId"] = "UIGuide_LongLin_2",
            },
        ["UIGuide_LongLin_3"] = {
            ["ContentES"] = "Una vez que el Polvo corrompido se disipa por completo, la Escama de Zhuyin activada atrae a los Filthoids. Entonces, el Polvo corrompido reaparece cerca y se condensa progresivamente.",
            ["TextMapId"] = "UIGuide_LongLin_3",
            },
        ["UIGuide_LongLin_4"] = {
            ["ContentES"] = "Elimina a todos los Filthoids antes de que el Polvo corrompido se condense por completo permite recolectar la Escama de Zhuyin con éxito.",
            ["TextMapId"] = "UIGuide_LongLin_4",
            },
        ["UIGuide_LongPressedSkills"] = {
            ["ContentES"] = "Algunas habilidades producen efectos diferentes dependiendo de si <H>se mantienen</> o <H>simplemente se pulsan</>.",
            ["TextMapId"] = "UIGuide_LongPressedSkills",
            },
        ["UIGuide_MirrorPuzzle_1"] = {
            ["ContentES"] = "Este dispositivo de medición fue colocado aquí por Luno, la exploradora. Una vez activado, reúne los datos que ella busca. Gíralo a la posición correcta y actívalo para reclamar las recompensas que dejó para los viajeros bondadosos.",
            ["TextMapId"] = "UIGuide_MirrorPuzzle_1",
            },
        ["UIGuide_ModTendency_1"] = {
            ["ContentES"] = "La parte superior de una casilla de Cuña Demoníaca muestra su <H>Afinidad</> (si la hay).",
            ["TextMapId"] = "UIGuide_ModTendency_1",
            },
        ["UIGuide_ModTendency_2"] = {
            ["ContentES"] = "La esquina superior izquierda de una Cuña Demoníaca muestra su <H>Afinidad</> (si la hay).",
            ["TextMapId"] = "UIGuide_ModTendency_2",
            },
        ["UIGuide_ModTendency_3"] = {
            ["ContentES"] = "Equipar cualquier Cuña Demoníaca en una casilla <H>Neutral</> <H>no cambia</> la tolerancia requerida. Equipar una Cuña Demoníaca <H>Neutral</> en cualquier casilla <H>no cambia</> la tolerancia requerida.",
            ["TextMapId"] = "UIGuide_ModTendency_3",
            },
        ["UIGuide_ModTendency_4"] = {
            ["ContentES"] = "Cuando la <H>Afinidad</> de una Cuña Demoníaca coincide con la de la casilla, se crea una sinergia: la <H>Tolerancia requerida se reduce</>.",
            ["TextMapId"] = "UIGuide_ModTendency_4",
            },
        ["UIGuide_ModTendency_5"] = {
            ["ContentES"] = "Cuando la <H>Afinidad</> de una Cuña Demoníaca es diferente de la de la casilla, se produce una incompatibilidad: la <H>Tolerancia requerida aumenta</>.",
            ["TextMapId"] = "UIGuide_ModTendency_5",
            },
        ["UIGuide_MonsterExitMechanism_1"] = {
            ["ContentES"] = "Unidades enemigas aparecen periódicamente desde este pasaje. El pasaje puede ser sellado únicamente <H>atacando puntos débiles específicos con la estrategia correcta</>.",
            ["TextMapId"] = "UIGuide_MonsterExitMechanism_1",
            },
        ["UIGuide_MonsterExitMechanism_2"] = {
            ["ContentES"] = "Unidades enemigas aparecen periódicamente desde este pasaje. Puedes <H>interactuar con ciertos dispositivos</> o <H>derrotar todos los enemigos</> para sellar el pasaje.",
            ["TextMapId"] = "UIGuide_MonsterExitMechanism_2",
            },
        ["UIGuide_Online_01_01"] = {
            ["ContentES"] = "Al realizar un encargo privado solo o con amigos, otros jugadores <H>no pueden</> unirse a medio camino.",
            ["TextMapId"] = "UIGuide_Online_01_01",
            },
        ["UIGuide_Online_01_02"] = {
            ["ContentES"] = "Al realizar un encargo público solo o con amigos, otros jugadores <H>pueden</> unirse a medio camino.",
            ["TextMapId"] = "UIGuide_Online_01_02",
            },
        ["UIGuide_Online_02_01"] = {
            ["ContentES"] = "En modo solo, un encargo privado empezará inmediatamente una vez que lo selecciones.",
            ["TextMapId"] = "UIGuide_Online_02_01",
            },
        ["UIGuide_Online_02_02"] = {
            ["ContentES"] = "En modo coop, un encargo privado requerirá que todos los miembros <H>confirmen en un plazo de 10 segundos</>. Una vez que todos confirmen o el tiempo se acabe, empezará el encargo.",
            ["TextMapId"] = "UIGuide_Online_02_02",
            },
        ["UIGuide_Online_03_01"] = {
            ["ContentES"] = "En el modo solo para encargos públicos, el sistema buscará durante <H>10 segundos</> un encargo en curso para que te unas a mitad de camino. Si no se encuentra una partida, comenzarás el encargo desde el principio. La búsqueda puede ser cancelada en cualquier momento durante la ventana de 10 segundos.",
            ["TextMapId"] = "UIGuide_Online_03_01",
            },
        ["UIGuide_Online_03_02"] = {
            ["ContentES"] = "En modo coop para encargos públicos, el sistema buscará durante <H>10 segundos</> un encargo en curso para que te unas a mitad de camino con tu grupo; si una partida es encontrada, comenzarás luego de que <H>todos los miembros del equipo hayan confirmado</>. Si no se encuentra una partida, tu equipo comenzará el encargo desde el principio. La búsqueda puede ser cancelada en cualquier momento por cualquier integrante del grupo durante la ventana de 10 segundos.",
            ["TextMapId"] = "UIGuide_Online_03_02",
            },
        ["UIGuide_Online_04_01"] = {
            ["ContentES"] = "Tanto en modo solo como en coop, los objetivos de encargos siguen siendo los mismos. Pero la <H>dificultad</> <H>aumenta</> con el número de jugadores. Cuanto más grande sea el equipo, más enemigos aparecerán y mayor será su nivel.",
            ["TextMapId"] = "UIGuide_Online_04_01",
            },
        ["UIGuide_Online_04_02"] = {
            ["ContentES"] = "Al final de cada ronda en cualquier Encargo ∞, se lleva a cabo una votación. Los jugadores que voten continuar pasarán a la siguiente ronda, mientras los que elijan retirarse saldrán. La elección de cada jugador <H>no afecta la de los demás</>.",
            ["TextMapId"] = "UIGuide_Online_04_02",
            },
        ["UIGuide_Online_04_03"] = {
            ["ContentES"] = "Cuando cualquier miembro del equipo llegue al punto de evacuación, comenzará una cuenta regresiva de <H>30 segundos</>. El encargo finalizará automáticamente cuando el temporizador finalice, o si todos los miembros del equipo llegan al Punto de evacuación durante la cuenta regresiva, el encargo finalizará inmediatamente.",
            ["TextMapId"] = "UIGuide_Online_04_03",
            },
        ["UIGuide_Online_05_01"] = {
            ["ContentES"] = "Cada miembro del equipo posee un número limitado de posibilidades de revivir. Al ser derrotado, comenzará un temporizador de 20 segundos. Si no seleccionas “Revivir” antes de que el tiempo termine, el encargo fracasará.",
            ["TextMapId"] = "UIGuide_Online_05_01",
            },
        ["UIGuide_Online_05_02"] = {
            ["ContentES"] = "Cuando un miembro del equipo elije revivir durante un encargo coop, otros jugadores pueden asistirlo acercándose a él, acelerando el proceso de resurrección.",
            ["TextMapId"] = "UIGuide_Online_05_02",
            },
        ["UIGuide_Online_06_01"] = {
            ["ContentES"] = "Los equipos formados antes de iniciar el encargo público permanecerán intactos luego de que el encargo termine, mientras que los jugadores que se unieron a mitad de camino abandonarán el equipo una vez completado el encargo.",
            ["TextMapId"] = "UIGuide_Online_06_01",
            },
        ["UIGuide_OverloadShield"] = {
            ["ContentES"] = "Escudo adicional del personaje obtenido mediante ciertos medios. El Escudo Ultra se <H>consumirá primero</> al recibir daño. El límite del Escudo Ultra aumenta a medida que sube el <H>Nivel del personaje</>.",
            ["TextMapId"] = "UIGuide_OverloadShield",
            },
        ["UIGuide_PerfectDodge"] = {
            ["ContentES"] = "Al enfrentar enemigos fuertes en el Capítulo Crepúsculo, <H>esquivar</> al último momento antes de ser golpeado, <H>ralentizará</> los enemigos cercanos por un corto periodo de tiempo.",
            ["TextMapId"] = "UIGuide_PerfectDodge",
            },
        ["UIGuide_PetPan_01"] = {
            ["ContentES"] = "Paniemon — ¡el más inteligente de todos los Geniemons! Sus rastros pueden encontrarse por todas partes.",
            ["TextMapId"] = "UIGuide_PetPan_01",
            },
        ["UIGuide_PetPan_02"] = {
            ["ContentES"] = "Síguelos, y podrías encontrarte con algo maravilloso.",
            ["TextMapId"] = "UIGuide_PetPan_02",
            },
        ["UIGuide_PetPan_Title"] = {
            ["ContentES"] = "¡Ve a rastrear al Paniemon!",
            ["TextMapId"] = "UIGuide_PetPan_Title",
            },
        ["UIGuide_Pet_1"] = {
            ["ContentES"] = "Los <H>Geniemons</> ya se encuentran disponibles. Ahora puedes encontrar <H>Geniemons</> en varias ubicaciones por el mundo.",
            ["TextMapId"] = "UIGuide_Pet_1",
            },
        ["UIGuide_Pet_2"] = {
            ["ContentES"] = "Pueden brindar diversos tipos de apoyo. Usa Latas de alta calidad y administra bien tus intentos de alimentación para aumentar considerablemente tus posibilidades de hacerte amigo de un Geniemon.",
            ["TextMapId"] = "UIGuide_Pet_2",
            },
        ["UIGuide_Phantom_1_1"] = {
            ["ContentES"] = "Durante una <H>exploración del mundo</> o un <H>encargo en solo</>, puedes invocar hasta <H>2</> Compañeros de combate al mismo tiempo.",
            ["TextMapId"] = "UIGuide_Phantom_1_1",
            },
        ["UIGuide_Phantom_1_2"] = {
            ["ContentES"] = "Durante un <H>Encargo de 2 jugadores</>, cada jugador solo puede invocar <H>1</> Compañero de combate.",
            ["TextMapId"] = "UIGuide_Phantom_1_2",
            },
        ["UIGuide_Phantom_1_3"] = {
            ["ContentES"] = "Durante un <H>Encargo con 3 o más jugadores</>, <H>no pueden invocarse Compañeros de combate</>.",
            ["TextMapId"] = "UIGuide_Phantom_1_3",
            },
        ["UIGuide_Phantom_2_1"] = {
            ["ContentES"] = "Mientras exploras el <H>mundo</>, puedes usar <H>Sello: Recordatorio</> para <H>retirar</> a tus Compañeros de combate en cualquier momento.",
            ["TextMapId"] = "UIGuide_Phantom_2_1",
            },
        ["UIGuide_Phantom_2_2"] = {
            ["ContentES"] = "Durante los <h>Encargos</> o al desafiar <H>Ecos nocturnos</>, <H>no puedes retirar</> a tus Compañeros de combate.",
            ["TextMapId"] = "UIGuide_Phantom_2_2",
            },
        ["UIGuide_Phantom_3_1"] = {
            ["ContentES"] = "Durante la <H>exploración del mundo</>, si un Compañero de combate es derrotado, puede ser <H>reinvocado</> mediante el sello correspondiente.",
            ["TextMapId"] = "UIGuide_Phantom_3_1",
            },
        ["UIGuide_Phantom_3_2"] = {
            ["ContentES"] = "Durante los <H>Encargos</>, si un Compañero de combate es derrotado, acércate y <H>mantén</> &Interactive& para <H>rescatarlo</>.",
            ["TextMapId"] = "UIGuide_Phantom_3_2",
            },
        ["UIGuide_Phantom_3_2_Phone"] = {
            ["ContentES"] = "Durante los <H>Encargos</>, si un Compañero de combate es derrotado, acércate y <H>mantén</> el botón interactivo para <H>rescatarlo</>.",
            ["TextMapId"] = "UIGuide_Phantom_3_2_Phone",
            },
        ["UIGuide_Phantom_3_3"] = {
            ["ContentES"] = "En las etapas de <H>Ecos nocturnos</>, los Compañeros caídos <H>no pueden ser invocados</> o <H>rescatados</>.",
            ["TextMapId"] = "UIGuide_Phantom_3_3",
            },
        ["UIGuide_Phantom_4_1"] = {
            ["ContentES"] = "Los Compañeros de combate consumen tanto Cordura como munición en batalla. Acercarse a la munición soltada por enemigos puede reponer las reservas de munición.",
            ["TextMapId"] = "UIGuide_Phantom_4_1",
            },
        ["UIGuide_QiTianDeng_1"] = {
            ["ContentES"] = "<H>Linternas celestiales</> flotan sobre las aguas del Río del Olvido. Destruirlas con un arma a distancia hace caer sus Flores-linterna, creando en la superficie del agua una zona de refugio que se reduce progresivamente, ayudándote a resistir la erosión de la Grieta del Olvido. Puedes moverte dentro de esta zona y recuperar PV.",
            ["TextMapId"] = "UIGuide_QiTianDeng_1",
            },
        ["UIGuide_Reading"] = {
            ["ContentES"] = "Puedes encontrar objetos legibles como libros, notas y cartas esparcidas por el mundo.",
            ["TextMapId"] = "UIGuide_Reading",
            },
        ["UIGuide_RelayMechanism_1"] = {
            ["ContentES"] = "Atacar una <H>Rueda Phoxynamo</> alternará su estado de activación. Si la <H>Rueda Phoxynamo</> es <H>azul</>, se encuentra <H>activa</>. Si aparece <H>naranja</>, se encuentra <H>inactiva</>.",
            ["TextMapId"] = "UIGuide_RelayMechanism_1",
            },
        ["UIGuide_RelayMechanism_2"] = {
            ["ContentES"] = "Algunas <H>Ruedas Phoxynamo</> <H>volverán automáticamente</> a su <H>estado original</> luego de un tiempo establecido tras un cambio de estado.",
            ["TextMapId"] = "UIGuide_RelayMechanism_2",
            },
        ["UIGuide_Rouge_1"] = {
            ["ContentES"] = "El espacio dentro del Abismo es inestable y cambia constantemente. Luego de completar cada fase, aparecerán nuevas puertas que llevan a distintos tipos de zonas. Elige tu camino y continúa tu exploración.",
            ["TextMapId"] = "UIGuide_Rouge_1",
            },
        ["UIGuide_Rouge_2_1"] = {
            ["ContentES"] = "Zona de Abisoide: Centrado en combate. Derrota los Abisoides para ganar recompensas como Brasas.",
            ["TextMapId"] = "UIGuide_Rouge_2_1",
            },
        ["UIGuide_Rouge_2_2"] = {
            ["ContentES"] = "Zona de Eco: Contiene eventos impredecibles conocidos como encuentros.",
            ["TextMapId"] = "UIGuide_Rouge_2_2",
            },
        ["UIGuide_Rouge_2_3"] = {
            ["ContentES"] = "Zona de Descanso: Una zona segura donde puedes intercambiar Brasas por suministros, restaurar PV y recuperar Cordura.",
            ["TextMapId"] = "UIGuide_Rouge_2_3",
            },
        ["UIGuide_Run_PC"] = {
            ["ContentES"] = "Mantén &Avoid& para correr.",
            ["TextMapId"] = "UIGuide_Run_PC",
            },
        ["UIGuide_Run_Phone"] = {
            ["ContentES"] = "Mantén presionado el botón para correr.",
            ["TextMapId"] = "UIGuide_Run_Phone",
            },
        ["UIGuide_SIDEWAYSJUMP"] = {
            ["ContentES"] = "Cuando te encuentres cerca de una pared escalable, mantén una dirección y presiona &Jump& <H>repetidamente</> para saltar hacia los lados y realizar saltos consecutivos en la pared.",
            ["TextMapId"] = "UIGuide_SIDEWAYSJUMP",
            },
        ["UIGuide_Saiqi_1"] = {
            ["ContentES"] = "Presiona &Skill1& para que Psyche cree 1 [Fantasma] y luego se proyecte hacia adelante. Esta habilidad se puede usar en cualquier momento sin interrumpir la acción actual de Psyche.",
            ["TextMapId"] = "UIGuide_Saiqi_1",
            },
        ["UIGuide_Saiqi_1_Gamepad"] = {
            ["ContentES"] = "Presiona &GamepadUseSkill& + &Attack& para que Psyche cree 1 [Fantasma] y luego se proyecte hacia adelante. Esta habilidad se puede usar en cualquier momento sin interrumpir la acción actual de Psyche.",
            ["TextMapId"] = "UIGuide_Saiqi_1_Gamepad",
            },
        ["UIGuide_Saiqi_1_Phone"] = {
            ["ContentES"] = "Presiona el botón para que Psyche cree 1 [Fantasma] y luego se proyecte hacia adelante. Esta habilidad se puede usar en cualquier momento sin interrumpir la acción actual de Psyche.",
            ["TextMapId"] = "UIGuide_Saiqi_1_Phone",
            },
        ["UIGuide_Saiqi_2"] = {
            ["ContentES"] = "Presiona &Skill2& para que Psyche entre en estado [Metamorfosis Radiante] y obtenga la habilidad de volar. En estado [Metamorfosis Radiante], Psyche solo puede usar habilidades y disparar. En estado [Metamorfosis Radiante], [Tejido de Crisálida Onírica] se reemplaza por [Fototaxis]: Se lanza hacia adelante y dispara [Polvo Etéreo] que se fija automáticamente en un enemigo aleatorio, causando Daño Anemo al impactar.",
            ["TextMapId"] = "UIGuide_Saiqi_2",
            },
        ["UIGuide_Saiqi_2_Gamepad"] = {
            ["ContentES"] = "Presiona &GamepadUseSkill& + &Interactive& para que Psyche entre en estado [Metamorfosis Radiante] y obtenga la habilidad de volar. En estado [Metamorfosis Radiante], Psyche solo puede usar habilidades y disparar. En estado [Metamorfosis Radiante], [Tejido de Crisálida Onírica] se reemplaza por [Fototaxis]: Se lanza hacia adelante y dispara [Polvo Etéreo] que se fija automáticamente en un enemigo aleatorio, causando Daño Anemo al impactar.",
            ["TextMapId"] = "UIGuide_Saiqi_2_Gamepad",
            },
        ["UIGuide_Saiqi_2_Phone"] = {
            ["ContentES"] = "Presiona el botón para que Psyche entre en estado [Metamorfosis Radiante] y obtenga la habilidad de volar. En estado [Metamorfosis Radiante], Psyche solo puede usar habilidades y disparar. En estado [Metamorfosis Radiante], [Tejido de Crisálida Onírica] se reemplaza por [Fototaxis]: Se lanza hacia adelante y dispara [Polvo Etéreo] que se fija automáticamente en un enemigo aleatorio, causando Daño Anemo al impactar.",
            ["TextMapId"] = "UIGuide_Saiqi_2_Phone",
            },
        ["UIGuide_Shadow_1"] = {
            ["ContentES"] = "Usa el <H>Sello de compañero de combate</> para invocar aliados en batalla. Arrastra los Sellos de compañero de combate a la Mochila táctica para habilitar las invocaciones.",
            ["TextMapId"] = "UIGuide_Shadow_1",
            },
        ["UIGuide_Shadow_2"] = {
            ["ContentES"] = "Mantén &OpenBattleWheel& para invocar aliados, que luchará junto a tu personaje actual.",
            ["TextMapId"] = "UIGuide_Shadow_2",
            },
        ["UIGuide_ShanYe_1"] = {
            ["ContentES"] = "Utiliza la función Atracción del Nexo Mecánico para hacer girar las aspas, generar una corriente de aire y abrir la puerta mecánica.",
            ["TextMapId"] = "UIGuide_ShanYe_1",
            },
        ["UIGuide_Sojourns_01"] = {
            ["ContentES"] = "<Highlight>Fragmentos de memoria</> desbloqueados. Selecciona el icono en el Santuario para acceder.",
            ["TextMapId"] = "UIGuide_Sojourns_01",
            },
        ["UIGuide_Sojourns_01_Pad"] = {
            ["ContentES"] = "<Highlight>Fragmentos de memoria</> ahora desbloqueados. Pulsa en el Santuario para acceder.",
            ["TextMapId"] = "UIGuide_Sojourns_01_Pad",
            },
        ["UIGuide_Sojourns_02"] = {
            ["ContentES"] = "Los <Highlight>Fragmentos de memoria</> capturan fragmentos de tiempo y memoria.",
            ["TextMapId"] = "UIGuide_Sojourns_02",
            },
        ["UIGuide_Sojourns_03"] = {
            ["ContentES"] = "Visita <Highlight>Antología del tiempo</> para ver historias de las diferentes etapas de la vida de un personaje.",
            ["TextMapId"] = "UIGuide_Sojourns_03",
            },
        ["UIGuide_Sojourns_03_Pad"] = {
            ["ContentES"] = "Pulsa para visitar <Highlight>Antología del tiempo</> y explorar historias de distintas etapas de la experiencia de un personaje.",
            ["TextMapId"] = "UIGuide_Sojourns_03_Pad",
            },
        ["UIGuide_Sojourns_04"] = {
            ["ContentES"] = "Cada personaje tiene su propio conjunto de historias.",
            ["TextMapId"] = "UIGuide_Sojourns_04",
            },
        ["UIGuide_Sojourns_04_Pad"] = {
            ["ContentES"] = "Pulsa para explorar la historia única de cada personaje.",
            ["TextMapId"] = "UIGuide_Sojourns_04_Pad",
            },
        ["UIGuide_Sojourns_05"] = {
            ["ContentES"] = "Usa <Highlight>Huella del alma</> para reconstruir estas historias. Algunas entradas tienen requisitos especiales.",
            ["TextMapId"] = "UIGuide_Sojourns_05",
            },
        ["UIGuide_Sojourns_06"] = {
            ["ContentES"] = "Cumple los requisitos para desbloquear historias y ganar recompensas.",
            ["TextMapId"] = "UIGuide_Sojourns_06",
            },
        ["UIGuide_Sojourns_06_Pad"] = {
            ["ContentES"] = "Las historias se desbloquearán una vez cumplidos los requisitos. Pulsa para reclamar las recompensas asociadas",
            ["TextMapId"] = "UIGuide_Sojourns_06_Pad",
            },
        ["UIGuide_Sojourns_07"] = {
            ["ContentES"] = "Las historias desbloqueadas pueden revisitar en <Highlight>Instante eterno</>.",
            ["TextMapId"] = "UIGuide_Sojourns_07",
            },
        ["UIGuide_Sp"] = {
            ["ContentES"] = "El recurso principal necesario para usar habilidades en batalla. <H>Se restaura</> con el tiempo.",
            ["TextMapId"] = "UIGuide_Sp",
            },
        ["UIGuide_SpecialDestructible_1"] = {
            ["ContentES"] = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.",
            ["TextMapId"] = "UIGuide_SpecialDestructible_1",
            },
        ["UIGuide_SpecialDestructible_2"] = {
            ["ContentES"] = "Por ejemplo, la <H>Criolita</> que cubre algunos cofres puede ser destruida con <H>Efecto Adicional: Contundente, Efecto Adicional: Pyro, o habilidades que infligen Daño Pyro</>.\
(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)",
            ["TextMapId"] = "UIGuide_SpecialDestructible_2",
            },
        ["UIGuide_SpecialDestructible_3"] = {
            ["ContentES"] = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.\
Las <H>Vid Umbro</> que cubren algunos cofres pueden ser destruidas con <H>Efecto Adicional: Cortante, Efecto Adicional: Lumino, o habilidades que infligen Daño Lumino</>.\
(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)",
            ["TextMapId"] = "UIGuide_SpecialDestructible_3",
            },
        ["UIGuide_SpecialDestructible_4"] = {
            ["ContentES"] = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.\
La <H>Grava</> que cubre algunos cofres puede ser destruida con <H>Efecto Adicional: Contundente</>.\
(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)",
            ["TextMapId"] = "UIGuide_SpecialDestructible_4",
            },
        ["UIGuide_SpecialDestructible_5"] = {
            ["ContentES"] = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.\
El <H>Escudo Lumino</> que cubre algunos cofres puede ser destruido con <H>Efecto Adicional: Perforante, Efecto Adiciona: Umbro, o habilidades que infligen Daño Umbro</>.\
(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)",
            ["TextMapId"] = "UIGuide_SpecialDestructible_5",
            },
        ["UIGuide_SpecialSideStoryUI1"] = {
            ["ContentES"] = "Es posible que encuentres algunas Misiones secundarias especiales. Están marcadas con un indicador azul en la lista de misiones.",
            ["TextMapId"] = "UIGuide_SpecialSideStoryUI1",
            },
        ["UIGuide_SpecialSideStoryUI2"] = {
            ["ContentES"] = "También pueden aparecer Misiones secundarias especiales durante la exploración. Completarlas puede desbloquear nuevas características o funciones.",
            ["TextMapId"] = "UIGuide_SpecialSideStoryUI2",
            },
        ["UIGuide_SwitchMaster_PC"] = {
            ["ContentES"] = "En áreas seguras, <H>mantén pulsado</> &Skill3& para cambiar {性别:al|a la} protagonista para explorar o interactuar.",
            ["TextMapId"] = "UIGuide_SwitchMaster_PC",
            },
        ["UIGuide_SwitchMaster_Phone"] = {
            ["ContentES"] = "En áreas seguras, <H>mantén pulsado</> el botón indicado para cambiar {性别:al|a la} protagonista para explorar o interactuar.",
            ["TextMapId"] = "UIGuide_SwitchMaster_Phone",
            },
        ["UIGuide_TaskAcceptance"] = {
            ["ContentES"] = "Al explorar un pueblo, interactuar con algunos residentes locales puede activar Misiones secundarias ocultas.",
            ["TextMapId"] = "UIGuide_TaskAcceptance",
            },
        ["UIGuide_Team_1"] = {
            ["ContentES"] = "Puedes invitar amigos para formar un equipo y completar un encargo juntos.",
            ["TextMapId"] = "UIGuide_Team_1",
            },
        ["UIGuide_Team_2_PC"] = {
            ["ContentES"] = "La <H>información del equipo</> se muestra en la parte <H>inferior izquierda</> de las interfaces de <H>Amigos</>, <H>Encargos</> y <H>Inicio</>.",
            ["TextMapId"] = "UIGuide_Team_2_PC",
            },
        ["UIGuide_Team_2_Phone"] = {
            ["ContentES"] = "La <H>información del equipo</> se muestra en la parte <H>superior derecha</> de las interfaces de <H>Amigos</>, <H>Encargos</> y <H>Inicio</>.",
            ["TextMapId"] = "UIGuide_Team_2_Phone",
            },
        ["UIGuide_Temple_1"] = {
            ["ContentES"] = "Meditando en ciertos lugares registrados, puedes acceder a las Pruebas de Ave espiritual, desbloqueando una serie de desafíos especiales.",
            ["TextMapId"] = "UIGuide_Temple_1",
            },
        ["UIGuide_Temple_2"] = {
            ["ContentES"] = "Recibirás recompensas de hasta cinco estrellas tras completar con éxito las pruebas por primera vez. Puedes repetirlas para obtener calificaciones más altas y mejores recompensas.",
            ["TextMapId"] = "UIGuide_Temple_2",
