            ["TextMapId"] = "UIGuide_TriggerEffect_2",
            },
        ["UIGuide_TriggerEffect_3"] = {
            ["ContentES"] = "Al infligir daño con una arma o ciertas habilidades, existe una probabilidad de activar un <H>Efecto Adicional</> elemental. La probabilidad está basada en la <H>probabilidad de activación</> del arma.",
            ["TextMapId"] = "UIGuide_TriggerEffect_3",
            },
        ["UIGuide_TurnTable"] = {
