            ["TextMapId"] = "UIGuide_WallJump_Phone",
            },
        ["UIGuide_WangXi_1"] = {
            ["ContentES"] = "La Grieta del Olvido erosiona continuamente a cualquier ser vivo que caiga en ella. Mientras permanezcas en este entorno, tus PV disminuirán constantemente.",
