            },
        ["UIGuide_WangXi_2"] = {
            ["ContentES"] = "La Grieta del Olvido está atravesada por las aguas del Río del Olvido. Entrar en contacto con estas aguas acelera considerablemente la pérdida de PV.",
            ["TextMapId"] = "UIGuide_WangXi_2",
            },
        ["UIGuide_WangXi_3"] = {
