  { MinKey = "UI_Vote_Retreat_Auto", MaxKey = "UI_WEAPON_NAME_AutoChess_31", Loader = function()
      return {
        ["UI_Vote_Retreat_Auto"] = {
            ["ContentES"] = "Si no se hace ninguna selección antes de que termine la cuenta regresiva, te retirarás automáticamente",
            ["TextMapId"] = "UI_Vote_Retreat_Auto",
            },
        ["UI_Vote_Retreat_Current"] = {
            ["ContentES"] = "Recompensas actuales",
            ["TextMapId"] = "UI_Vote_Retreat_Current",
            },
        ["UI_Vote_Retreat_Reward"] = {
            ["ContentES"] = "Retirarse permite obtener las recompensas según el progreso actual",
            ["TextMapId"] = "UI_Vote_Retreat_Reward",
            },
        ["UI_Vote_Select"] = {
            ["ContentES"] = "Elige el próximo movimiento",
            ["TextMapId"] = "UI_Vote_Select",
            },
        ["UI_Vote_Wave"] = {
            ["ContentES"] = "Oleada",
            ["TextMapId"] = "UI_Vote_Wave",
            },
        ["UI_WALNUTDUNGEON_REFRESH_TOAST"] = {
            ["ContentES"] = "Encargo actualizado. Sal y reinicia el desafío.",
            ["TextMapId"] = "UI_WALNUTDUNGEON_REFRESH_TOAST",
            },
        ["UI_WEAPON_DESC_10101"] = {
            ["ContentES"] = "El arma que porta Berenica es una hoja adornada con oro. El metal negro del arma no pertenece a ningún material ordinario. Es evidente que no es un arma que los aldeanos de la Isla del Purgatorio pudieran poseer.",
            ["TextMapId"] = "UI_WEAPON_DESC_10101",
            },
        ["UI_WEAPON_DESC_10102"] = {
            ["ContentES"] = "Que una celebración sin límites pueda llenar todos los vacíos que genera tu soledad.",
            ["TextMapId"] = "UI_WEAPON_DESC_10102",
            },
        ["UI_WEAPON_DESC_10103"] = {
            ["ContentES"] = "Una espada de una mano de origen desconocido que ha estado a tu lado desde siempre. Quizás, algún día, se convierta en la llave que una el pasado con el presente.",
            ["TextMapId"] = "UI_WEAPON_DESC_10103",
            },
        ["UI_WEAPON_DESC_10104"] = {
            ["ContentES"] = "La mejor defensa es un buen ataque. Pero no olvides que descansar lo suficiente también es muy importante.",
            ["TextMapId"] = "UI_WEAPON_DESC_10104",
            },
        ["UI_WEAPON_DESC_10105"] = {
            ["ContentES"] = "Al igual que tú, emprenderé el viaje hacia El más allá, más allá de las arenas que se deslizan.",
            ["TextMapId"] = "UI_WEAPON_DESC_10105",
            },
        ["UI_WEAPON_DESC_10198"] = {
            ["ContentES"] = "Una espada de una mano forjada con la tecnología más avanzada de refinamiento, el arma predilecta de los caballeros leales.",
            ["TextMapId"] = "UI_WEAPON_DESC_10198",
            },
        ["UI_WEAPON_DESC_10199"] = {
            ["ContentES"] = "Una espada de una mano común, hecha del metal más barato, incluso si se rompe no representa una gran pérdida.",
            ["TextMapId"] = "UI_WEAPON_DESC_10199",
            },
        ["UI_WEAPON_DESC_10201"] = {
            ["ContentES"] = "¡Bésame! ¡Bésame mucho! Antes de que llegue el mañana, antes de que la juventud se desvanezca, antes de que la muerte nos separe.",
            ["TextMapId"] = "UI_WEAPON_DESC_10201",
            },
        ["UI_WEAPON_DESC_10202"] = {
            ["ContentES"] = "Un Arma de Asta traída desde Huaxu, la tierra natal de los Tejestrellas. La forma y el color de su hoja se inspiran en una planta propia de Huaxu: el sauce, que simboliza el hogar. Aunque recorran cada rincón de Atlasia tejiendo el cielo estrellado, algún día regresarán a su frondosa tierra natal.",
            ["TextMapId"] = "UI_WEAPON_DESC_10202",
            },
        ["UI_WEAPON_DESC_10203"] = {
            ["ContentES"] = "Entre el frío de la luna y el calor del sol, la vida humana se va consumiendo.",
            ["TextMapId"] = "UI_WEAPON_DESC_10203",
            },
        ["UI_WEAPON_DESC_10204"] = {
            ["ContentES"] = "Planté una semilla en la tierra helada, esperando una cosecha que tal vez nunca llegue.",
            ["TextMapId"] = "UI_WEAPON_DESC_10204",
            },
        ["UI_WEAPON_DESC_10205"] = {
            ["ContentES"] = "Guadaña empleada por los Caballeros del Iris Sagrado de la Iglesia Elysiana. ¡Exaltación divina! He contemplado la luz con que los dioses se apiadan del mundo, haciendo pedazos la prolongada ignorancia de los necios.",
            ["TextMapId"] = "UI_WEAPON_DESC_10205",
            },
        ["UI_WEAPON_DESC_10206"] = {
            ["ContentES"] = "La podredumbre es el término de toda existencia. Acéptala, y podrás alcanzar un refugio eterno.",
            ["TextMapId"] = "UI_WEAPON_DESC_10206",
            },
        ["UI_WEAPON_DESC_10207"] = {
            ["ContentES"] = "En el cristal azul profundo se encierra la furia del océano. Las súplicas del enemigo son notas musicales disonantes, destinadas a ser silenciadas en la partitura de este reino.",
            ["TextMapId"] = "UI_WEAPON_DESC_10207",
            },
        ["UI_WEAPON_DESC_10208"] = {
            ["ContentES"] = "Una paloma blanca que lucha por defender la dignidad, jura entregar cada una de sus plumas para defender la paz.",
            ["TextMapId"] = "UI_WEAPON_DESC_10208",
            },
        ["UI_WEAPON_DESC_10209"] = {
            ["ContentES"] = "La daga ensangrentada apunta a tu corazón. Antes de que la lava se enfríe todavía tienes tiempo de huir.",
            ["TextMapId"] = "UI_WEAPON_DESC_10209",
            },
        ["UI_WEAPON_DESC_10298"] = {
            ["ContentES"] = "Una lanza forjada con la tecnología más avanzada de refinamiento, el arma predilecta de los guardias más firmes.",
            ["TextMapId"] = "UI_WEAPON_DESC_10298",
            },
        ["UI_WEAPON_DESC_10299"] = {
            ["ContentES"] = "Una lanza común, forjada en metal barato, incluso si se rompe no representa una gran pérdida.",
            ["TextMapId"] = "UI_WEAPON_DESC_10299",
            },
        ["UI_WEAPON_DESC_10301"] = {
            ["ContentES"] = "¡Arde, arde, arde! Las llamas del juicio reducirán a cenizas toda la maldad de este mundo.",
            ["TextMapId"] = "UI_WEAPON_DESC_10301",
            },
        ["UI_WEAPON_DESC_10302"] = {
            ["ContentES"] = "Solo un poder supremo puede imponer una ley de hierro.",
            ["TextMapId"] = "UI_WEAPON_DESC_10302",
            },
        ["UI_WEAPON_DESC_10303"] = {
            ["ContentES"] = "Un sable inmaculado que al cortar el aire, ansía teñirse de rojo carmesí.",
            ["TextMapId"] = "UI_WEAPON_DESC_10303",
            },
        ["UI_WEAPON_DESC_10304"] = {
            ["ContentES"] = "Que se quiebren los ecos del pasado, y se inaugure la paz para todas las generaciones.",
            ["TextMapId"] = "UI_WEAPON_DESC_10304",
            },
        ["UI_WEAPON_DESC_10398"] = {
            ["ContentES"] = "Un espadón forjado con la tecnología más avanzada de refinamiento, el arma predilecta de los sirvientes silenciosos.",
            ["TextMapId"] = "UI_WEAPON_DESC_10398",
            },
        ["UI_WEAPON_DESC_10399"] = {
            ["ContentES"] = "Un mandoble común, forjado en metal barato, incluso si se rompe no representa una gran pérdida.",
            ["TextMapId"] = "UI_WEAPON_DESC_10399",
            },
        ["UI_WEAPON_DESC_10401"] = {
            ["ContentES"] = "Un lobo solitario que no tiene nada más que sus colmillos. Frente a él se extiende el camino perdido del destino, bajo sus patas, las cenizas de su tierra natal.",
            ["TextMapId"] = "UI_WEAPON_DESC_10401",
            },
        ["UI_WEAPON_DESC_10402"] = {
            ["ContentES"] = "Cuando se hundió en las oscuras olas del mar, el portador de las hojas dobles alzó su posesión más preciada en ofrenda a los dioses… sin embargo estos no le concedieron misericordia.",
            ["TextMapId"] = "UI_WEAPON_DESC_10402",
            },
        ["UI_WEAPON_DESC_10403"] = {
            ["ContentES"] = "Ahora, eres el cazador de las profundidades.",
            ["TextMapId"] = "UI_WEAPON_DESC_10403",
            },
        ["UI_WEAPON_DESC_10404"] = {
            ["ContentES"] = "Mareas furiosas que quiebran la escarcha; entre el rugir del viento, destella el filo helado.",
            ["TextMapId"] = "UI_WEAPON_DESC_10404",
            },
        ["UI_WEAPON_DESC_10498"] = {
            ["ContentES"] = "Un par de hojas dobles forjadas con la tecnología más avanzada de refinamiento, el arma predilecta de los asesinos errantes.",
            ["TextMapId"] = "UI_WEAPON_DESC_10498",
            },
        ["UI_WEAPON_DESC_10499"] = {
            ["ContentES"] = "Un sable curvo forjado con la tecnología más avanzada de refinamiento, el arma predilecta de los caminantes solitarios.",
            ["TextMapId"] = "UI_WEAPON_DESC_10499",
            },
        ["UI_WEAPON_DESC_10501"] = {
            ["ContentES"] = "Un sueño del pasado que mira hacia el futuro.",
            ["TextMapId"] = "UI_WEAPON_DESC_10501",
            },
        ["UI_WEAPON_DESC_10502"] = {
            ["ContentES"] = "El cielo se compadece de toda vida, y su lluvia benévola da amparo a todos los seres.",
            ["TextMapId"] = "UI_WEAPON_DESC_10502",
            },
        ["UI_WEAPON_DESC_10503"] = {
            ["ContentES"] = "No son solo los sentimientos conectan a las personas. La espada látigo, al retorcerse y entrelazarse, también permite que los corazones se abran profundamente entre sí.",
            ["TextMapId"] = "UI_WEAPON_DESC_10503",
            },
        ["UI_WEAPON_DESC_10504"] = {
            ["ContentES"] = "Restos de coral que yacen marchitos sobre la playa, donde se condensan los fragmentos de sueños del mar infinito.",
            ["TextMapId"] = "UI_WEAPON_DESC_10504",
            },
        ["UI_WEAPON_DESC_10598"] = {
            ["ContentES"] = "Una espada látigo forjada con la tecnología más avanzada de refinamiento, el arma predilecta de los caminantes solitarios.",
            ["TextMapId"] = "UI_WEAPON_DESC_10598",
            },
        ["UI_WEAPON_DESC_10599"] = {
            ["ContentES"] = "Una espada látigo común, forjado en metal barato, incluso si se rompe no representa una gran pérdida.",
            ["TextMapId"] = "UI_WEAPON_DESC_10599",
            },
        ["UI_WEAPON_DESC_10601"] = {
            ["ContentES"] = "Un sable de diseño poco común que aparece en la célebre tragedia Momiji: Crónica de la rebelión. Algunos dicen que la mancha roja en su empuñadura es la sangre derramada cuando su primer dueño mató a su propio rey.",
            ["TextMapId"] = "UI_WEAPON_DESC_10601",
            },
        ["UI_WEAPON_DESC_10602"] = {
            ["ContentES"] = "En los ojos de quien va a morir se refleja una flor de cerezo carmesí que desciende desde la rama.",
            ["TextMapId"] = "UI_WEAPON_DESC_10602",
            },
        ["UI_WEAPON_DESC_10603"] = {
            ["ContentES"] = "En la empuñadura se distingue una inscripción apenas legible: “Alabada sea la Iglesia Elysiana”. Gracias por llevar la sagrada bendición de los Nueve Dioses al Principado de Yashnia, tierra de pecadores.",
            ["TextMapId"] = "UI_WEAPON_DESC_10603",
            },
        ["UI_WEAPON_DESC_10698"] = {
            ["ContentES"] = "Un sable curvo forjado con la tecnología más avanzada de refinamiento, el arma predilecta de los caminantes solitarios.",
            ["TextMapId"] = "UI_WEAPON_DESC_10698",
            },
        ["UI_WEAPON_DESC_10699"] = {
            ["ContentES"] = "Una katana común, forjada en metal barato, incluso si se rompe no representa una gran pérdida.",
            ["TextMapId"] = "UI_WEAPON_DESC_10699",
            },
        ["UI_WEAPON_DESC_110101"] = {
            ["ContentES"] = "“Cero”. El origen. El inicio de todo.",
            ["TextMapId"] = "UI_WEAPON_DESC_110101",
            },
        ["UI_WEAPON_DESC_150101"] = {
            ["ContentES"] = "“La Diosa volvió a hablar al Séptimo Santo: ‘Con esta espada, forjo este pacto contigo y tus descendientes. Quienes tengan una determinación inquebrantable recibirán mi bendición y, con ella, la protección de esta espada’”.",
            ["TextMapId"] = "UI_WEAPON_DESC_150101",
            },
        ["UI_WEAPON_DESC_20101"] = {
            ["ContentES"] = "Reconstruir el mundo a través de la verdad.",
            ["TextMapId"] = "UI_WEAPON_DESC_20101",
            },
        ["UI_WEAPON_DESC_20102"] = {
            ["ContentES"] = "Un error que se abre paso desde la espiral de muertes acumuladas.",
            ["TextMapId"] = "UI_WEAPON_DESC_20102",
            },
        ["UI_WEAPON_DESC_20103"] = {
            ["ContentES"] = "El estruendo del oráculo resonará en las cabezas de todos los herejes.",
            ["TextMapId"] = "UI_WEAPON_DESC_20103",
            },
        ["UI_WEAPON_DESC_20198"] = {
            ["ContentES"] = "Pistola forjada con la tecnología más avanzada de refinamiento, el arma predilecta de los pastores.",
            ["TextMapId"] = "UI_WEAPON_DESC_20198",
            },
        ["UI_WEAPON_DESC_20199"] = {
            ["ContentES"] = "Una pistola común, forjada en metal barato, incluso si se rompe no representa una gran pérdida.",
            ["TextMapId"] = "UI_WEAPON_DESC_20199",
            },
        ["UI_WEAPON_DESC_20201"] = {
            ["ContentES"] = "Dentro de la espiral de muertes acumuladas, los errores no hacen más que multiplicarse.",
            ["TextMapId"] = "UI_WEAPON_DESC_20201",
            },
        ["UI_WEAPON_DESC_20203"] = {
            ["ContentES"] = "El mar infinito late sin cesar con el pulso de la vida, abundante, vibrante, y a la vez interminable.",
            ["TextMapId"] = "UI_WEAPON_DESC_20203",
            },
        ["UI_WEAPON_DESC_20205"] = {
            ["ContentES"] = "El estruendo del oráculo resonará en las cabezas de todos los herejes.",
            ["TextMapId"] = "UI_WEAPON_DESC_20205",
            },
        ["UI_WEAPON_DESC_20296"] = {
            ["ContentES"] = "Pistolas Dobles forjadas con la tecnología más avanzada de refinamiento, el arma predilecta de los pastores.",
            ["TextMapId"] = "UI_WEAPON_DESC_20296",
            },
        ["UI_WEAPON_DESC_20298"] = {
            ["ContentES"] = "Pistolas Dobles comunes, forjadas en metal barato, incluso si se rompen no representan una gran pérdida.",
            ["TextMapId"] = "UI_WEAPON_DESC_20298",
            },
        ["UI_WEAPON_DESC_20301"] = {
            ["ContentES"] = "Que el penitente no mire al cielo, las innumerables estrellas jamás escuchan las plegarias de los pecadores.",
            ["TextMapId"] = "UI_WEAPON_DESC_20301",
            },
        ["UI_WEAPON_DESC_20302"] = {
            ["ContentES"] = "Bajo el telón de la noche, se ven zapatos rojos, las rosas cubiertas de rocío, fuegos artificiales, la pólvora flota en el aire, sí, esto es un gran festín.",
            ["TextMapId"] = "UI_WEAPON_DESC_20302",
            },
        ["UI_WEAPON_DESC_20303"] = {
            ["ContentES"] = "Para volver a la naturaleza es necesario fundirse con las cenizas y perderse en la tierra.",
            ["TextMapId"] = "UI_WEAPON_DESC_20303",
            },
        ["UI_WEAPON_DESC_20304"] = {
            ["ContentES"] = "Huesos mecánicos templados en bronce, espinas que regresan de la ruina, y forjan un alma heroica.",
            ["TextMapId"] = "UI_WEAPON_DESC_20304",
            },
        ["UI_WEAPON_DESC_20305"] = {
            ["ContentES"] = "El fuego de la justicia cabalga sobre miles de proyectiles de plata mientras caen al suelo, grabando el edicto de los dioses en los corazones de cada hereje.",
            ["TextMapId"] = "UI_WEAPON_DESC_20305",
            },
        ["UI_WEAPON_DESC_20398"] = {
            ["ContentES"] = "Un lanzagranadas forjado con la tecnología más avanzada de refinamiento, el arma predilecta de los valientes asediadores de ciudades.",
            ["TextMapId"] = "UI_WEAPON_DESC_20398",
            },
        ["UI_WEAPON_DESC_20399"] = {
            ["ContentES"] = "Un lanzagranadas fabricado usando las técnicas más recientes de refinamiento. Este modelo cuenta con la máxima recomendación de los herreros. Su equilibrio perfecto entre calidad y precio lo ha convertido en una opción popular entre los viajeros de toda Atlasia.",
            ["TextMapId"] = "UI_WEAPON_DESC_20399",
            },
        ["UI_WEAPON_DESC_20401"] = {
            ["ContentES"] = "Solo después del lamento, el mundo regresa al silencio.",
            ["TextMapId"] = "UI_WEAPON_DESC_20401",
            },
        ["UI_WEAPON_DESC_20402"] = {
            ["ContentES"] = "Sembrar flores en la piel para que desde dentro brote la destrucción.",
            ["TextMapId"] = "UI_WEAPON_DESC_20402",
            },
        ["UI_WEAPON_DESC_20403"] = {
            ["ContentES"] = "Un arma de fuego empleada por los Caballeros del Iris Sagrado de la Iglesia Elysiana. ¡Exaltación divina! Juramos que el mensaje de los Nueve Dioses resonará en cada rincón de Atlasia.",
            ["TextMapId"] = "UI_WEAPON_DESC_20403",
            },
        ["UI_WEAPON_DESC_20405"] = {
            ["ContentES"] = "¿Ah, sí? ¿Atlasia va a ser destruida? Me da igual, que se destruya todo.",
            ["TextMapId"] = "UI_WEAPON_DESC_20405",
            },
        ["UI_WEAPON_DESC_20498"] = {
            ["ContentES"] = "Una escopeta forjada con la tecnología más avanzada de refinamiento, el arma predilecta de los cazadores experimentados.",
            ["TextMapId"] = "UI_WEAPON_DESC_20498",
            },
        ["UI_WEAPON_DESC_20499"] = {
            ["ContentES"] = "Una escopeta común, forjada en metal barato, incluso si se rompe no representa una gran pérdida.",
            ["TextMapId"] = "UI_WEAPON_DESC_20499",
            },
        ["UI_WEAPON_DESC_20501"] = {
            ["ContentES"] = "Ante el brutal dolor que provocan las balas, capaz de desgarrar la piel, los huesos y el alma... ¿cuánto tiempo podrán resistir la bondad, la firmeza y el valor?",
            ["TextMapId"] = "UI_WEAPON_DESC_20501",
            },
        ["UI_WEAPON_DESC_20502"] = {
            ["ContentES"] = "El arma utilizada por “El Cuervo” de Los Abandonados. ¡Escucha! ¡Esta es la furia de los exiliados! ¡Son las campanas que resuenan por la caída del Imperio!",
            ["TextMapId"] = "UI_WEAPON_DESC_20502",
            },
        ["UI_WEAPON_DESC_20503"] = {
            ["ContentES"] = "Un lanzallamas empleado por los Caballeros del Iris Sagrado de la Iglesia Elysiana. ¡Exaltación divina! Que el fuego sagrado descienda sobre nosotros, en tu nombre, juramos reducir a cenizas toda corrupción.",
            ["TextMapId"] = "UI_WEAPON_DESC_20503",
            },
        ["UI_WEAPON_DESC_20504"] = {
            ["ContentES"] = "Una ametralladora empuñada por los Caballeros del Iris Sagrado de la Iglesia Elysiana. “¡Santa exaltación! Si tan solo contemplamos el primer rayo del amanecer, aunque nuestro camino esté sembrado de espinas, lo acogeremos como un dulce socorro.”",
            ["TextMapId"] = "UI_WEAPON_DESC_20504",
            },
        ["UI_WEAPON_DESC_20505"] = {
            ["ContentES"] = "La perfección del triángulo, bendecida por la diosa; donde el arte de la belleza se forja en un filo letal.",
            ["TextMapId"] = "UI_WEAPON_DESC_20505",
            },
        ["UI_WEAPON_DESC_20506"] = {
            ["ContentES"] = "Las nubes se apartan, dejando que dos pavos reales se lancen al vuelo; sobre una alfombra de brocado florido, una bailarina esboza sus pasos gráciles.",
            ["TextMapId"] = "UI_WEAPON_DESC_20506",
            },
        ["UI_WEAPON_DESC_20507"] = {
            ["ContentES"] = "El joven marinero, siempre demasiado preocupado por guardar el mástil antes de la tempestad, nunca contabilizó las notas de amor ocultas bajo las olas, sin saber que cada una de las canciones de la sirena era una serenata destinada sólo a él.",
            ["TextMapId"] = "UI_WEAPON_DESC_20507",
            },
        ["UI_WEAPON_DESC_20509"] = {
            ["ContentES"] = "Con una pluma de nieve tejí una jaula delgada, sellando el mundo salvaje en su interior.",
            ["TextMapId"] = "UI_WEAPON_DESC_20509",
            },
        ["UI_WEAPON_DESC_20510"] = {
            ["ContentES"] = "Mi espada agitó la luna plateada reflejada en un río de sueños; en el silencio del tiempo, otro otoño se desvanecía bajo su brillo plateado.",
            ["TextMapId"] = "UI_WEAPON_DESC_20510",
            },
        ["UI_WEAPON_DESC_20598"] = {
            ["ContentES"] = "Un rifle de asalto perfeccionado con las últimas técnicas de tratamiento de superficies, preferido por las vanguardias duras que lideran desde el frente.",
            ["TextMapId"] = "UI_WEAPON_DESC_20598",
            },
        ["UI_WEAPON_DESC_20599"] = {
            ["ContentES"] = "Una ametralladora fabricada con las últimas técnicas de fundición y dorado. Este modelo es una de las mejores recomendaciones de los herreros. Su equilibrio perfecto entre calidad y precio lo ha convertido en una opción popular entre los viajeros de Atlasia.",
            ["TextMapId"] = "UI_WEAPON_DESC_20599",
            },
        ["UI_WEAPON_DESC_20601"] = {
            ["ContentES"] = "Tú, alma solitaria, te encuentras en el corazón de la llama ardiente, pero voluntariamente te conviertes en un grano de arena, arrastrado por los vientos del cambio. Así comienza tu renacimiento y la reivindicación de tu destino de nuevo.",
            ["TextMapId"] = "UI_WEAPON_DESC_20601",
            },
        ["UI_WEAPON_DESC_20602"] = {
            ["ContentES"] = "La cuerda del arco zumba, indicando que los enemigos están a tiro. Mantén la calma, amigo mío: tu enemigo no tiene ni una mínima oportunidad.",
            ["TextMapId"] = "UI_WEAPON_DESC_20602",
            },
        ["UI_WEAPON_DESC_20603"] = {
            ["ContentES"] = "Ningún ser viviente sabe qué hay más allá del Mar Nebuloso. Quizás, en ese caos primordial, una sola flor invisible aún se atreva a florecer.",
            ["TextMapId"] = "UI_WEAPON_DESC_20603",
            },
        ["UI_WEAPON_DESC_20604"] = {
            ["ContentES"] = "Un sonido de vida y muerte, un lamento desgarrador.",
            ["TextMapId"] = "UI_WEAPON_DESC_20604",
            },
        ["UI_WEAPON_DESC_20698"] = {
            ["ContentES"] = "Un arco refinado con las últimas técnicas de tratamiento de superficies, el preferido de los exploradores silenciosos que atacan sin ser vistos.",
            ["TextMapId"] = "UI_WEAPON_DESC_20698",
            },
        ["UI_WEAPON_DESC_20699"] = {
            ["ContentES"] = "Un arco común y corriente. Fabricado con el metal más barato, así que no hay problema si se rompe.",
            ["TextMapId"] = "UI_WEAPON_DESC_20699",
            },
        ["UI_WEAPON_DESC_310101"] = {
            ["ContentES"] = "“¿Qué ves en mí? No tengo nada que venderte. No tuve nada desde el principio.” “No, Lynn. Tú sí. Lo que quiero es tu ’sueño’.”",
            ["TextMapId"] = "UI_WEAPON_DESC_310101",
            },
        ["UI_WEAPON_DESC_530101"] = {
            ["ContentES"] = "Vuela. Vuela... Aunque tengas alas falsas, como pequeñas semillas de flores que surcan el viento, vuela sobre las almenas, vuela sobre la tierra helada, vuela a través de la larga noche y elévate hacia esa luz abrasadora, ese sol cálido.",
            ["TextMapId"] = "UI_WEAPON_DESC_530101",
            },
        ["UI_WEAPON_NAME_10101"] = {
            ["ContentES"] = "Hoja de Ámbar Radiante",
            ["TextMapId"] = "UI_WEAPON_NAME_10101",
            },
