        ["UI_WeaponSkin_Des_3010101"] = {
            ["ContentES"] = "Un verdadero pescador nunca vuelve a casa con las manos vacías. Menos mal que el mercado de pescado tenía una liquidación: 80 monedas cada una, pero nadie tiene por qué enterarse.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010101",
            },
        ["UI_WeaponSkin_Des_3010102"] = {
            ["ContentES"] = "Justo antes de colisionar, las estrellas se despidieron con un beso. Sus susurros fragmentados se convirtieron en rayos de fuego: el aliento de los amantes a la deriva por la Vía Láctea.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010102",
            },
        ["UI_WeaponSkin_Des_3010104"] = {
            ["ContentES"] = "Un espadón de diseño inusual, dicho para encarnar el amor de un padre: firme, instructivo y un poco traumático.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010104",
            },
        ["UI_WeaponSkin_Des_3010105"] = {
            ["ContentES"] = "¡Miau!",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010105",
            },
        ["UI_WeaponSkin_Des_3010106"] = {
            ["ContentES"] = "Un verdadero maestro no necesita arma: un bambú roto o una rama seca son suficientes para escribir una leyenda que nadie puede detener.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010106",
            },
        ["UI_WeaponSkin_Des_3010107"] = {
            ["ContentES"] = "Partir el cielo y la tierra, y apaciguar los ocho horizontes con un banquete.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010107",
            },
        ["UI_WeaponSkin_Des_3010201"] = {
            ["ContentES"] = "Trucha congelada: firme, sabrosa y conservable. Dura más que la carne enlatada, el film transparente e incluso tu instinto de supervivencia.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010201",
            },
        ["UI_WeaponSkin_Des_3010202"] = {
            ["ContentES"] = "Una espada singular, destinada a encarnar la autoridad de un padre: firme, formativa… y lo suficientemente traumática.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010202",
            },
        ["UI_WeaponSkin_Des_3010203"] = {
            ["ContentES"] = "¡Miauu~!",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010203",
            },
        ["UI_WeaponSkin_Des_3010301"] = {
            ["ContentES"] = "¿Dónde está el sol? Mira, está bailando en la palma de mi mano.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010301",
            },
        ["UI_WeaponSkin_Des_3010302"] = {
            ["ContentES"] = "¡Grrr-miau!",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010302",
            },
        ["UI_WeaponSkin_Des_3010303"] = {
            ["ContentES"] = "¡Miauu!",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010303",
            },
        ["UI_WeaponSkin_Des_3010401"] = {
            ["ContentES"] = "Una sola nota rompe el silencio, despertándola de un sueño de verano y tocando suavemente las cuerdas de su corazón.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010401",
            },
        ["UI_WeaponSkin_Des_3010402"] = {
            ["ContentES"] = "Las olas saltan bajo los pasos del bailarín: el ritmo del verano rompe el aire. Aquí, la rapsodia alcanza su máximo esplendor: salvaje y brillante.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010402",
            },
        ["UI_WeaponSkin_Des_3010403"] = {
            ["ContentES"] = "Un arma de asta singular, dicho para encarnar el amor de un padre: firme, instructivo y un poco traumático.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010403",
            },
        ["UI_WeaponSkin_Des_3010404"] = {
            ["ContentES"] = "¡Miaaaou —!",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010404",
            },
        ["UI_WeaponSkin_Des_3010501"] = {
            ["ContentES"] = "¿Qué mal plan podría tener un adorable tiburóncito?",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010501",
            },
        ["UI_WeaponSkin_Des_3010502"] = {
            ["ContentES"] = "Miau ♪ miau-miau-miau ♪ miau-miau ♪♪",
