            },
        ["ZhiLiuEntrust_Jump_Tips"] = {
            ["ContentES"] = "¿Quieres teletransportarte a Zhiliu?",
            ["TextMapId"] = "ZhiLiuEntrust_Jump_Tips",
            },
        ["ZhiLiuEntrust_Lock_PretextTasks"] = {
